from g123_core import make_q, make_lesson
from fig_helpers_g123 import table_fig, bars_fig, fig_clock, fig_traffic_sign


def _q(b, num, d, p, c, w, e, s='', h='', fig=None):
    return make_q(f'DD2-B{b:02d}-{num:03d}', d, p, c, w, e, s, h, fig)


def get_lessons_part1():
    lessons = []

    # BÀI 1: Em yêu quê hương
    lessons.append(make_lesson(
        'daoduc2-c1', 'daoduc2-b01', 'Bài 1. Em yêu Quê hương', 1,
        'Nhận biết vẻ đẹp thiên nhiên, con người, truyền thống quê hương và biết thể hiện tình yêu quê hương bằng việc làm phù hợp lứa tuổi',
        ['Quê hương thân yêu', 'Cảnh đẹp và truyền thống', 'Giữ gìn quê hương'],
        [
            _q(1, 1, 'basic', 'Quê hương của mỗi người được hiểu giản dị và gần gũi nhất là nơi nào?', 'Nơi em sinh ra, lớn lên hoặc nơi gắn bó thân thuộc với ông bà, cha mẹ và dòng họ gia đình', ['Chỉ là những thành phố thật lớn có nhiều tòa nhà cao', 'Chỉ là nơi có khu vui chơi giải trí đắt tiền', 'Bất kì nơi nào em xem trên tivi'],
               'Dù là làng quê yên bình hay phố phường nhộn nhịp, nơi gắn bó tuổi thơ và gia đình đều là quê hương thân thương.', 'Khái niệm Quê hương',
               fig=table_fig('Tình yêu Quê hương', ['Lĩnh vực', 'Việc bé làm được'], [['Cảnh quan', 'Không xả rác bừa'], ['Cây xanh', 'Chăm cây quanh nhà'], ['Di tích', 'Giữ trật tự chung'], ['Văn hóa', 'Học hỏi truyền thống']])),
            _q(1, 2, 'basic', 'Những nét đẹp nào sau đây thường gắn liền với tình yêu quê hương đất nước của học sinh lớp 2?', 'Tự hào giới thiệu cảnh đẹp, món ăn ngon, lễ hội truyền thống quê mình và góp sức giữ đường làng ngõ phố sạch đẹp', ['Chê bai quê mình nghèo và bẩn hơn nơi khác', 'Vứt rác bừa bãi ra sông hồ và công viên', 'Vẽ bậy tên mình lên tường di tích lịch sử'],
               'Yêu quê hương bắt đầu từ lòng tự hào và ý thức giữ gìn từng góc nhỏ xung quanh mình.', 'Biểu hiện yêu quê hương'),
            _q(1, 3, 'basic', 'Khi cùng gia đình đi tham quan di tích lịch sử, đền chùa hay bảo tàng ở địa phương, em cần giữ thái độ và hành vi nào?', 'Đi nhẹ nói khẽ, ăn mặc gọn gàng lịch sự, giữ vệ sinh chung và không tự ý sờ nắn hiện vật quý', ['Chạy nhảy la hét ầm ĩ trêu bạn trong khu tưởng niệm', 'Khắc chữ lên thân cây cổ thụ hay cột đá', 'Xả vỏ bánh kẹo xuống sân di tích'],
               'Thái độ trang nghiêm tôn trọng di tích thể hiện lòng biết ơn đối với thế hệ cha ông.', 'Ứng xử tại di tích'),
            _q(1, 4, 'basic', 'Hành động nào dưới đây của bạn nhỏ lớp 2 góp phần làm quê hương ngày càng xanh – sạch – đẹp?', 'Tham gia ngày Chủ nhật xanh cùng gia đình quét dọn ngõ xóm, nhặt rác bỏ đúng nơi quy định và tưới cây xanh trước nhà', ['Hái trụi hết hoa trong công viên mang về nhà', 'Đổ nước bẩn ra ngoài đường đi chung', 'Đốt lá khô cạnh gốc cây xanh'],
               'Mỗi hành động nhỏ giữ môi trường sạch sẽ là một món quà thiết thực tặng quê hương.', 'Việc làm xanh quê hương'),
            _q(1, 5, 'basic', 'Lễ hội truyền thống hay sản phẩm làng nghề nổi tiếng của quê hương (như gốm Bát Tràng, trống Đọi Tam, hoa Sa Đéc...) mang lại ý nghĩa gì?', 'Giữ gìn bản sắc văn hóa dân tộc, tạo việc làm tự hào cho người dân và thu hút bạn bè khắp nơi đến tìm hiểu', ['Chỉ làm cho đường phố thêm đông đúc mệt mỏi', 'Không có giá trị gì trong thời đại hiện nay', 'Chỉ dành riêng cho người lớn tuổi'],
               'Hiểu và trân trọng giá trị làng nghề, lễ hội quê hương giúp giữ gìn hồn cốt dân tộc.', 'Truyền thống địa phương'),
            _q(1, 6, 'basic', 'Câu thơ quen thuộc "Quê hương là chùm khế ngọt / Cho con trèo hái mỗi ngày" của nhà thơ Đỗ Trung Quân gợi lên cảm xúc gì?', 'Tình cảm gắn bó dịu ngọt, thân thương sâu sắc với những hình ảnh bình dị thân quen của tuổi thơ', ['Nỗi buồn chán muốn bỏ quê hương đi xa', 'Sợ hãi khi nhìn thấy cây khế ngoài vườn', 'Chỉ nói về giá bán quả khế ngoài chợ'],
               'Quê hương luôn gắn với những kỉ niệm mộc mạc nhưng ấm áp theo ta suốt cuộc đời.', 'Cảm xúc về quê hương'),
            _q(1, 7, 'application', 'Trường em tổ chức ngày hội "Em yêu quê hương", cô giáo mời mỗi bạn giới thiệu một điều đặc sắc về nơi mình ở. Bạn Nam ngại ngùng bảo: "Quê tớ chẳng có nhà chọc trời như thủ đô, chẳng có gì hay để kể". Em khuyên Nam thế nào?', 'Khuyên Nam tự tin kể về cánh đồng lúa xanh, con sông quê, món bánh truyền thống hay tình làng nghĩa xóm ấm áp vì nơi nào cũng có vẻ đẹp riêng đáng tự hào', ['Đồng ý bảo Nam đừng lên giới thiệu nữa', 'Bảo Nam bịa ra một khu vui chơi không có thật', 'Chê quê của Nam thật buồn tẻ'],
               'Mỗi miền quê Việt Nam đều mang vẻ đẹp độc đáo riêng đáng được yêu mến và giới thiệu.', 'Tự hào nét đẹp địa phương'),
            _q(1, 8, 'application', 'Cuối tuần lớp 2A phát động chiến dịch "Ngõ phố không rác". Sau 1 buổi sáng dọn dẹp, tổ 1 gom được 12 túi rác tái chế, tổ 2 gom được 15 túi, tổ 3 gom được 14 túi và tổ 4 gom được 13 túi. Tổ nào thu gom được nhiều nhất và tổng cộng cả 4 tổ gom được bao nhiêu túi?', 'Tổ 2 nhiều nhất (15 túi); cả 4 tổ gom được 54 túi', ['Tổ 3 nhiều nhất; tổng 52 túi', 'Tổ 2 nhiều nhất; tổng 50 túi', 'Tổ 1 nhiều nhất; tổng 54 túi'],
               '12 + 15 + 14 + 13 = 54 túi; cột Tổ 2 cao nhất đạt 15 túi.', 'Đọc biểu đồ giữ sạch quê hương',
               fig=bars_fig('Túi rác tái chế thu gom lớp 2A', ['Tổ 1', 'Tổ 2', 'Tổ 3', 'Tổ 4'], [12, 15, 14, 13], 'túi')),
            _q(1, 9, 'application', 'Khi dẫn một người bạn ở tỉnh khác về thăm quê mình chơi, em nên cư xử thế nào để bạn cảm thấy yêu mến quê hương em?', 'Niềm nở đón tiếp, dẫn bạn thăm những cảnh đẹp đặc trưng, kể câu chuyện hay về quê mình và giữ nếp sống văn minh lịch sự', ['Chê bạn không biết đường quê mình', 'Chỉ ngồi trong phòng đóng cửa xem điện thoại', 'Khoác lác chê quê của bạn ấy xấu hơn'],
               'Sự hiếu khách và lòng tự hào đúng mực giúp bạn bè thêm yêu quý con người quê hương em.', 'Đón bạn thăm quê'),
            _q(1, 10, 'application', 'Ở công viên khu phố mới trồng thêm 20 cây xanh bóng mát. Buổi chiều đi chơi, em thấy một bạn nhỏ định đu lên cành cây non làm gãy ngọn. Em nên ứng xử ra sao?', 'Nhẹ nhàng khuyên bạn buông tay xuống vì cây non rất dễ gãy chết, nhắc nhau bảo vệ để cây mau lớn cho bóng mát cả khu phố', ['Cười cổ vũ bạn trèo cao hơn nữa', 'Cùng bạn bẻ thêm cành cây khác làm kiếm chơi', 'Lờ đi quay mặt bước qua'],
               'Bảo vệ cây xanh công cộng là trách nhiệm chung giữ lá phổi xanh cho quê hương.', 'Bảo vệ cây xanh nơi ở'),
            _q(1, 11, 'application', 'Bạn Hà sống ở thành phố từ nhỏ nhưng quê nội lại ở vùng biển miền Trung. Theo em, Hà có nên tìm hiểu và tự hào về vùng biển quê nội của mình không?', 'Rất nên! Cả thành phố nơi Hà sinh sống lớn lên và quê nội miền biển đều là quê hương thân thương gắn bó máu thịt với Hà', ['Không, chỉ nơi nào hiện tại ở mới là quê', 'Không, về quê xa lắm không cần quan tâm', 'Chỉ quan tâm khi nào được đi tắm biển'],
               'Yêu cả nơi mình sinh sống lẫn quê cha đất tổ là tình cảm rộng mở đáng quý.', 'Gắn bó hai miền quê'),
            _q(1, 12, 'application', 'Trong giờ học Ngoại khóa, cô giáo nhờ các em vẽ tranh chủ đề "Quê hương tươi đẹp". Đề tài nào sau đây phù hợp nhất với chủ đề?', 'Vẽ cảnh trường học sạch đẹp, hàng cây xanh mát, dòng sông quê êm đềm hoặc những người dân quê đang lao động vui vẻ', ['Vẽ cảnh rác thải chất đống bốc mùi trên đường', 'Vẽ hình quái vật ngoài hành tinh bắn phá thành phố', 'Tô đen kín cả tờ giấy trắng'],
               'Tranh vẽ cảnh đẹp bình yên và nét văn hóa lao động thể hiện sinh động tình yêu quê hương.', 'Sáng tạo chủ đề quê hương'),
            _q(1, 13, 'advanced', 'Khu phố tổ chức trồng hoa dọc 2 bên con đường dài 30 mét: cứ cách 5 mét lại trồng 1 khóm hoa ở mỗi bên đường (tính cả 2 đầu đường, mỗi bên 7 khóm hoa). Hỏi cả hai bên đường đã trồng được bao nhiêu khóm hoa làm đẹp khu phố?', '14 khóm hoa', ['12 khóm hoa', '15 khóm hoa', '16 khóm hoa'],
               'Mỗi bên đường có 30 : 5 + 1 = 7 khóm hoa -> hai bên đường có 7 x 2 = 14 khóm hoa rực rỡ!', 'Toán làm đẹp khu phố'),
            _q(1, 14, 'advanced', 'Vì sao tục ngữ Việt Nam có câu: "Quê hương mỗi người chỉ một / Như là chỉ một mẹ thôi"?', 'Vì quê hương sinh dưỡng gắn bó với cội nguồn máu thịt và tuổi thơ không gì thay thế được, cần được mỗi người suốt đời yêu thương và giữ gìn', ['Vì mỗi người chỉ được phép đi du lịch một lần', 'Vì tên quê hương không thể viết hai lần', 'Vì chỉ người sống ở nông thôn mới có quê'],
               'Tình yêu quê hương thiêng liêng tựa tình mẫu tử, nuôi dưỡng tâm hồn mỗi người Việt.', 'Ý nghĩa câu thơ Quê hương'),
            _q(1, 15, 'advanced', 'Khi trưởng thành hoặc ngay từ hôm nay là học sinh lớp 2, cách thiết thực nhất để đóng góp xây dựng quê hương giàu đẹp là gì?', 'Chăm chỉ học tập tốt, rèn đạo đức văn minh, sống có trách nhiệm với môi trường và lan tỏa những hành động tử tế trong cộng đồng', ['Chỉ chờ người khác làm giàu cho quê hương', 'Đợi đến khi 50 tuổi mới bắt đầu góp sức', 'Bỏ quê hương đi mà không bao giờ nhớ lại'],
               'Học tập tốt hôm nay chính là chuẩn bị tri thức và bàn tay xây dựng quê hương ngày mai!', 'Trách nhiệm với quê hương'),
        ]
    ))

    # BÀI 2: Kính trọng thầy giáo, cô giáo
    lessons.append(make_lesson(
        'daoduc2-c1', 'daoduc2-b02', 'Bài 2. Kính trọng Thầy giáo, Cô giáo', 2,
        'Biết ơn, kính trọng thầy giáo, cô giáo qua lời nói lễ phép, chăm chỉ học tập và những hành động tri ân chân thành',
        ['Tôn sư trọng đạo', 'Kính trọng thầy cô', 'Biết ơn người dạy dỗ'],
        [
            _q(2, 1, 'basic', 'Hành động nào dưới đây thể hiện rõ nhất lòng kính trọng, biết ơn đối với thầy giáo, cô giáo?', 'Lễ phép chào hỏi mỗi khi gặp, chăm chú nghe giảng, vâng lời chỉ bảo và chăm chỉ hoàn thành bài tập thầy cô giao', ['Nói chuyện riêng cười đùa khi thầy cô đang giảng bài', 'Nhăn mặt khó chịu khi thầy cô nhắc nhở lỗi sai', 'Đặt biệt danh không hay sau lưng thầy cô'],
               'Kính trọng thầy cô thể hiện hàng ngày qua thái độ học tập nghiêm túc và lời nói lễ phép.', 'Biểu hiện kính trọng thầy cô',
               fig=table_fig('Kính trọng Thầy cô', ['Hoàn cảnh', 'Cách ứng xử đúng'], [['Gặp thầy cô', 'Khoanh tay chào rõ'], ['Trong giờ học', 'Lắng nghe, giơ tay'], ['Được góp ý', 'Tiếp thu, sửa ngay'], ['Ngày 20 tháng 11', 'Làm thiệp chúc mừng']])),
            _q(2, 2, 'basic', 'Ngày Nhà giáo Việt Nam hằng năm để cả nước tôn vinh và gửi lời tri ân tới các thầy cô giáo là ngày nào?', 'Ngày 20 tháng 11', ['Ngày 1 tháng 6', 'Ngày 2 tháng 9', 'Ngày 8 tháng 3'],
               'Ngày 20/11 là Ngày Nhà giáo Việt Nam – dịp đặc biệt để học sinh bày tỏ lòng biết ơn thầy cô.', 'Ngày Nhà giáo Việt Nam'),
            _q(2, 3, 'basic', 'Khi thấy cô giáo đang bê chồng vở rất nặng đi từ phòng giáo viên sang lớp học, em nên làm gì?', 'Nhanh nhẹn chạy lại lễ phép nói "Cô ơi để con phụ bê giúp cô một ít ạ!" và cầm cẩn thận mang lên bàn giúp cô', ['Đứng nhìn cười rồi chạy vượt qua trước mặt cô', 'Đóng sầm cửa lớp lại để trêu cô', 'Làm ngơ coi như không nhìn thấy'],
               'Chủ động giúp thầy cô việc vừa sức là hành động đẹp đầy tình cảm của học trò ngoan.', 'Giúp đỡ thầy cô vừa sức'),
            _q(2, 4, 'basic', 'Khi thầy giáo hoặc cô giáo chỉ ra chỗ em viết còn ẩu hay làm sai một bài toán và nhắc em sửa lại, em cần có thái độ thế nào?', 'Lễ phép lắng nghe lời thầy cô chỉ bảo, nói "Dạ em cảm ơn cô ạ!" rồi sửa lại bài cẩn thận cho tiến bộ', ['Giận dỗi xé rách trang vở ngay trên bàn', 'Cãi lại rằng mình làm đúng rồi không cần sửa', 'Quay sang đổ lỗi cho bạn ngồi cạnh'],
               'Thầy cô góp ý là muốn giúp em giỏi hơn mỗi ngày; tiếp thu sửa lỗi là tôn trọng công sức thầy cô.', 'Tiếp thu lời nhắc nhở'),
            _q(2, 5, 'basic', 'Không chỉ với thầy cô đang dạy lớp 2 của mình, đối với các thầy cô dạy lớp 1 năm ngoái hoặc thầy cô dạy lớp khác trong trường, em cần cư xử ra sao?', 'Vẫn luôn kính trọng, nhớ ơn và vui vẻ chào hỏi lễ phép mỗi khi gặp lại', ['Quên luôn không cần chào vì không còn dạy mình nữa', 'Chỉ chào mỗi cô giáo chủ nhiệm hiện tại', 'Chạy trốn mỗi khi thấy thầy cô cũ đi ngang'],
               '"Một chữ cũng là thầy, nửa chữ cũng là thầy" – lòng biết ơn thầy cô cũ là đức tính thủy chung cao đẹp.', 'Biết ơn thầy cô cũ'),
            _q(2, 6, 'basic', 'Món quà ý nghĩa nhất mà học sinh lớp 2 có thể dâng tặng thầy cô giáo để thầy cô thật sự hạnh phúc là gì?', 'Những bông hoa điểm tốt, sự chăm ngoan tiến bộ từng ngày và tấm thiệp tự vẽ lời chúc chân thành', ['Những món đồ chơi thật đắt tiền xin từ bố mẹ', 'Sự lười biếng không chịu làm bài tập', 'Những lời hứa suông không thực hiện'],
               'Niềm vui lớn nhất của người thầy là nhìn thấy học trò mình ngoan ngoãn và trưởng thành mỗi ngày.', 'Món quà tri ân thầy cô'),
            _q(2, 7, 'application', 'Sắp đến ngày 20 tháng 11, nhóm của Lan định góp tiền mua một món quà đắt tiền tặng cô chủ nhiệm, nhưng bạn Minh nhà hoàn cảnh khó khăn không đủ tiền đóng nên rất buồn ngại. Lan nên đề xuất cách nào hay nhất?', 'Cả lớp cùng tự tay vẽ tranh, làm báo tường và viết những tấm thiệp giấy xinh xắn ghi lời chúc chân thành tặng cô – vừa ý nghĩa vừa công bằng cho mọi bạn', ['Bắt Minh phải về xin bằng được bố mẹ tiền đóng', 'Loại Minh ra khỏi nhóm tặng quà của lớp', 'Không tặng gì cả vì không có tiền mua quà đắt'],
               'Tình cảm chân thành tự tay làm mang giá trị tinh thần cao hơn vạn lần tiền bạc!', 'Quà 20/11 ấm áp gắn kết'),
            _q(2, 8, 'application', 'Bạn Hùng thường đến lớp hơi muộn vào buổi sáng lúc cô giáo đã bắt đầu tiết 1 được 5 phút. Theo đồng hồ chỉ 7 giờ 30 là giờ vào học, để tỏ lòng tôn trọng giờ giảng của cô và kỉ luật lớp, Hùng cần đi học thế nào?', 'Sửa thói quen ngủ dậy sớm hơn, có mặt ở lớp trước 7 giờ 30 để ổn định chỗ ngồi chào cô đúng giờ cùng các bạn', ['Cứ đi muộn nhưng gõ cửa thật nhẹ là được', 'Đợi hết tiết 1 mới bước vào lớp học tiết 2', 'Đứng ngoài cửa sổ ngó vào trêu các bạn'],
               'Đi học đúng giờ là biểu hiện thiết thực nhất của thái độ tôn trọng thầy cô và tập thể.', 'Tôn trọng giờ giảng',
               fig=fig_clock(7, 30, 'Giờ bắt đầu tiết học buổi sáng')),
            _q(2, 9, 'application', 'Trong giờ Mĩ thuật hôm nay có thầy giáo dạy thay vì cô giáo Mĩ thuật nghỉ ốm. Một số bạn bàn cuối rủ nhau quậy phá vì nghĩ "thầy dạy thay chắc không biết tên mình". Em nên làm gì?', 'Nhắc các bạn giữ trật tự lắng nghe và học tập nghiêm túc như với cô giáo thường ngày vì thầy giáo nào cũng tận tâm truyền dạy cho chúng ta', ['Hưởng ứng hò reo ném máy bay giấy cùng các bạn', 'Giả vờ ngủ gục trên bàn suốt cả tiết', 'Bày đồ chơi ra bàn chơi chung'],
               'Tôn trọng mọi thầy cô giáo dù chỉ dạy một tiết hay dạy thay thể hiện nhân cách đẹp của học sinh.', 'Tôn trọng thầy cô dạy thay'),
            _q(2, 10, 'application', 'Nhân ngày 20 tháng 11, khối 2 trường em tổ chức làm thiệp tri ân tặng các thầy cô. Lớp 2A làm được 28 tấm thiệp, lớp 2B làm 32 tấm, lớp 2C làm 30 tấm. Cả ba lớp làm được tổng cộng bao nhiêu tấm thiệp?', '90 tấm thiệp tri ân', ['80 tấm thiệp', '88 tấm thiệp', '92 tấm thiệp'],
               '28 + 32 + 30 = 90 tấm thiệp đầy tình cảm học trò!', 'Đọc biểu đồ tri ân',
               fig=bars_fig('Thiệp tri ân 20 tháng 11 khối 2', ['Lớp 2A', 'Lớp 2B', 'Lớp 2C'], [28, 32, 30], 'tấm')),
            _q(2, 11, 'application', 'Tan học trời mưa, bố bạn Mai đến đón và vô tình thấy cô giáo đứng chờ tạnh mưa ở nhà xe mà chưa có áo mưa. Mai nên gợi ý bố điều gì?', 'Lễ phép hỏi xem cô có đi cùng hướng đường không để bố con mình che ô đưa cô ra cổng hoặc cho cô mượn chiếc áo mưa dự phòng', ['Chạy thẳng qua vũng nước làm bắn ướt áo cô', 'Giả vờ không thấy cô để đi về thật nhanh', 'Ngồi yên trên xe cười nhìn cô bị ướt'],
               'Quan tâm sẻ chia với thầy cô khi gặp khó khăn nhỏ là tấm lòng nhân hậu đáng khen.', 'Quan tâm thầy cô ngày mưa'),
            _q(2, 12, 'application', 'Một bạn chuyển trường đi xa nhưng vẫn nhớ cô giáo dạy mình hồi lớp 1. Bạn ấy có thể làm gì để giữ tình cảm kính yêu với cô giáo cũ?', 'Nhờ bố mẹ gọi điện hoặc viết một lá thư tay ngắn kể về kết quả học tập mới và gửi lời hỏi thăm sức khỏe cô nhân dịp lễ Tết', ['Quên hẳn tên cô giáo vì đã chuyển trường', 'Chỉ nhớ khi nào cần xin điểm thưởng', 'Không dám nói chuyện vì ngại ngùng'],
               'Lòng biết ơn bền lâu vượt qua khoảng cách không gian là phẩm chất cao quý của "Tôn sư trọng đạo".', 'Giữ lòng biết ơn bền lâu'),
            _q(2, 13, 'advanced', 'Cô giáo chủ nhiệm lớp 2A có 35 học sinh. Dịp cuối học kì 1, mỗi bạn tự viết 2 điều biết ơn cô dán lên "Cây Tri ân" của lớp (mỗi lá thư là 1 chiếc lá). Nếu có 3 bạn vắng mặt hôm đó nhưng đã gửi bù sau, hỏi cuối cùng trên Cây Tri ân có tất cả bao nhiêu chiếc lá?', '70 chiếc lá tri ân', ['64 chiếc lá', '67 chiếc lá', '35 chiếc lá'],
               'Tất cả 35 bạn đều viết đủ mỗi bạn 2 lá: 35 x 2 = 70 chiếc lá tri ân rực rỡ!', 'Bài toán Cây Tri ân'),
            _q(2, 14, 'advanced', 'Vì sao ông cha ta dạy câu tục ngữ: "Không thầy đố mày làm nên" và "Muốn sang thì bắc cầu Kiều / Muốn con hay chữ thì yêu lấy thầy"?', 'Khẳng định vai trò to lớn của thầy cô trong việc truyền trao tri thức, rèn luyện nhân cách giúp học sinh trưởng thành thành người có ích', ['Vì chỉ có thầy cô mới biết xây cầu Kiều', 'Vì học sinh không cần tự học ở nhà', 'Vì chỉ ngày xưa mới cần đi học'],
               'Truyền thống "Tôn sư trọng đạo" là nét văn hóa ngàn đời tôn vinh sự học của dân tộc Việt Nam.', 'Truyền thống Tôn sư trọng đạo'),
            _q(2, 15, 'advanced', 'Nếu lỡ thấy cô giáo đang hơi mệt vì khàn giọng sau nhiều tiết giảng liên tiếp, ngoài việc giữ im lặng nghe lời, cả lớp có thể cùng làm hành động tinh tế nào để giúp cô?', 'Giữ trật tự tuyệt đối không để cô phải nhắc lớn tiếng, cử bạn lớp trưởng lễ phép rót mời cô cốc nước ấm và hăng hái học tập thật tốt', ['Ồn ào hơn nữa để thử xem cô nói to nổi không', 'Đề nghị nghỉ học luôn để đi chơi sân trường', 'Trêu chọc giọng nói khàn của cô'],
               'Sự tinh tế biết giữ im lặng khi cô mệt giọng quý giá hơn mọi lời khen ngợi.', 'Sự tinh tế của học trò'),
        ]
    ))

    # BÀI 3: Quý trọng người lao động
    lessons.append(make_lesson(
        'daoduc2-c1', 'daoduc2-b03', 'Bài 3. Quý trọng Người lao động', 3,
        'Nhận biết giá trị của mọi nghề nghiệp lương thiện trong xã hội và thể hiện thái độ tôn trọng, biết ơn người lao động',
        ['Quý trọng người lao động', 'Mọi nghề đều cao quý', 'Biết ơn thành quả lao động'],
        [
            _q(3, 1, 'basic', 'Những ai là những "người lao động" đang ngày đêm đóng góp làm đẹp và phục vụ cuộc sống hàng ngày của chúng ta?', 'Bác nông dân, cô công nhân, chú bộ đội, bác sĩ, cô giáo, cô lao công, chú thợ xây, người bán hàng và mọi người làm việc chân chính', ['Chỉ những người mặc quần áo thật sang trọng ngồi văn phòng', 'Chỉ những ngôi sao hát trên tivi', 'Những người không làm việc mà chỉ đi chơi'],
               'Mọi công việc chân chính tạo ra sản phẩm hay giúp ích cho xã hội đều đáng được trân trọng như nhau.', 'Nhận biết người lao động',
               fig=table_fig('Tri ân Người lao động', ['Nghề nghiệp', 'Đóng góp quý giá'], [['Bác nông dân', 'Trồng lúa, rau sạch'], ['Cô lao công', 'Giữ phố xá sạch đẹp'], ['Bác sĩ, y tá', 'Chăm sóc sức khỏe'], ['Chú thợ xây', 'Xây nhà, trường học']])),
            _q(3, 2, 'basic', 'Hạt gạo trắng dẻo thơm trong bát cơm mỗi bữa ăn hàng ngày là kết tinh mồ hôi công sức vất vả của ai?', 'Bác nông dân một nắng hai sương cày cấy, chăm sóc và thu hoạch ngoài đồng ruộng', ['Tự nhiên mọc sẵn trong nồi cơm điện', 'Chỉ do cửa hàng siêu thị tạo ra không cần trồng', 'Do trời mưa rơi xuống'],
               'Nhớ công ơn bác nông dân giúp em biết trân trọng từng hạt cơm, không ăn uống lãng phí bỏ mứa.', 'Biết ơn bác nông dân'),
            _q(3, 3, 'basic', 'Khi gặp cô lao công đang quét rác dọn sạch sân trường hoặc đường phố dưới trời nắng hay đêm khuya, thái độ đúng nhất của em là gì?', 'Mỉm cười lễ phép chào cô, không vứt rác bừa bãi làm thêm việc cho cô và thầm cảm ơn cô đã giữ môi trường sạch đẹp', ['Bịt mũi chạy thật nhanh và bảo nghề quét rác thật bẩn', 'Cố tình ném vỏ kẹo ngay chỗ cô vừa quét sạch', 'Cười chê bộ quần áo bảo hộ lao động của cô'],
               'Không có cô chú công nhân vệ sinh, phố phường sẽ ngập rác bệnh tật; nghề vệ sinh môi trường vô cùng cao quý!', 'Kính trọng cô lao công'),
            _q(3, 4, 'basic', 'Hành động nào sau đây thể hiện lòng biết ơn và trân trọng công sức của những người lao động làm ra đồ dùng, thức ăn?', 'Ăn hết phần cơm không bỏ phí, giữ gìn sách vở quần áo bền sạch và nói lời cảm ơn lịch sự với người phục vụ', ['Xé giấy vở trắng tinh ném làm pháo giấy chơi', 'Cắn nát đồ ăn rồi vứt bỏ lung tung', 'Quát tháo người bán hàng hoặc bác bảo vệ'],
               'Tiết kiệm và giữ gìn sản phẩm lao động là cách tri ân thiết thực nhất gửi tới người tạo ra chúng.', 'Trân trọng thành quả lao động'),
            _q(3, 5, 'basic', 'Trong xã hội hiện đại, câu nói nào thể hiện nhận thức ĐÚNG về giá trị giữa các nghề nghiệp chân chính?', 'Không có nghề nào sang hay hèn; mọi nghề lao động chân chính có ích cho cộng đồng đều bình đẳng và đáng kính trọng', ['Chỉ nghề làm giám đốc mới cao quý hơn các nghề khác', 'Nghề sửa xe hay bán rau không cần phải tôn trọng', 'Chỉ người học đại học mới là người lao động giỏi'],
               'Giá trị con người nằm ở sự cần cù trung thực và đóng góp cho xã hội, không phụ thuộc vào tên gọi nghề nghiệp.', 'Bình đẳng nghề nghiệp'),
            _q(3, 6, 'basic', 'Khi đi khám bệnh ở phòng y tế hay bệnh viện, thái độ lễ phép đúng mực với bác sĩ và cô chú y tá là gì?', 'Chào hỏi lễ phép, hợp tác làm theo hướng dẫn khám bệnh và nói "Cháu cảm ơn bác sĩ/cô y tá ạ!" sau khi khám xong', ['Khóc la giãy giụa ném đồ đạc trong phòng khám', 'Nói dối bác sĩ về chỗ đau của mình', 'Chê thuốc đắng rồi đổ đi'],
               'Bác sĩ và nhân viên y tế làm việc vất vả cứu chữa bệnh nhân nên rất cần sự hợp tác và lòng biết ơn.', 'Biết ơn nhân viên y tế'),
            _q(3, 7, 'application', 'Ở căn-tin trường có một số bạn ăn cơm trưa xong chỉ ăn vài thìa rồi đổ bỏ nửa khay cơm trắng vào thùng rác. Nhìn thấy vậy, em nên nhắc nhở các bạn điều gì?', 'Nhắc bạn lấy lượng cơm vừa đủ sức ăn để ăn hết sạch sẽ vì mỗi hạt cơm đều thấm đẫm công sức bác nông dân và cô cấp dưỡng nấu nướng', ['Hùa theo đổ bỏ bớt cơm đi cho nhanh ra chơi', 'Khen bạn ăn ít thế cho khỏi tốn thời gian', 'Vứt thêm cả thìa đũa vào thùng rác'],
               'Không lãng phí thức ăn là bài học đạo đức lớn gắn với lòng biết ơn người lao động.', 'Chống lãng phí thực phẩm'),
            _q(3, 8, 'application', 'Bố bạn Tùng làm nghề thợ sửa ống nước thường mặc áo dính bụi dầu. Một bạn trong lớp trêu chọc bảo bố Tùng làm nghề tay chân bẩn thỉu khiến Tùng rất buồn. Nếu là bạn thân của Tùng, em sẽ nói gì?', 'Bênh vực Tùng và giải thích: nếu không có bác thợ sửa ống nước thì cả khu phố mất nước sạch dùng, nghề lao động chân chính rất đáng tự hào!', ['Cười phụ họa cùng bạn kia để cho vui', 'Khuyên Tùng bảo bố nghỉ việc ở nhà luôn', 'Nói dối là bố Tùng làm phi công'],
               'Dũng cảm bảo vệ phẩm giá của người lao động chân chính trước lời chế giễu thiếu hiểu biết.', 'Bảo vệ phẩm giá nghề nghiệp'),
            _q(3, 9, 'application', 'Trường em tổ chức ngày hội "Tri ân Cô chú Phục vụ Trường học" (gồm cô cấp dưỡng, cô lao công, chú bảo vệ, bác thợ điện). Các lớp chuẩn bị những bó hoa giấy và lời chúc gửi tặng. Biểu đồ cho thấy số hoa lớp 2 làm tặng từng nhóm: Tổng cộng các bạn làm được bao nhiêu bông hoa?', '100 bông hoa (30 + 25 + 25 + 20)', ['85 bông hoa', '90 bông hoa', '110 bông hoa'],
               '30 + 25 + 25 + 20 = 100 bông hoa tươi thắm gửi tặng các cô chú lao động!', 'Đọc biểu đồ tri ân',
               fig=bars_fig('Hoa giấy lớp 2 tặng cô chú trường', ['Cô cấp dưỡng', 'Cô lao công', 'Chú bảo vệ', 'Bác thợ điện'], [30, 25, 25, 20], 'bông')),
            _q(3, 10, 'application', 'Buổi trưa hè trời nắng 38 độ, chú giao hàng (shipper) mồ hôi ướt đẫm mang gói sách vở bố đặt tới cổng nhà em. Khi em cùng bố ra nhận hàng, việc làm ấm áp vừa sức của em là gì?', 'Mỉm cười lễ phép chào chú, nói lời cảm ơn và xin phép bố rót mời chú một cốc nước lọc mát giải khát', ['Đóng sầm cổng lại không thèm chào chú câu nào', 'Chê chú giao chậm rồi đòi mở hộp ngay tại sân', 'Chỉ tay ra lệnh chú đặt xuống đất đi'],
               'Một cốc nước mát và lời cảm ơn chân thành xua tan mệt nhọc nắng gắt cho người lao động!', 'Ấm áp với người giao hàng'),
            _q(3, 11, 'application', 'Để làm ra 1 quyển vở học sinh em đang viết phải trải qua công sức của người trồng rừng lấy gỗ, công nhân nhà máy giấy, thợ in ấn kẻ dòng và cô bán sách. Hiểu điều đó giúp em sử dụng vở thế nào?', 'Viết nắn nót cẩn thận từng trang giấy, tận dụng giấy thừa làm nháp và không xé giấy trắng vứt bừa bãi', ['Xé nửa quyển vở mới gấp máy bay ném chơi', 'Mỗi trang chỉ viết 2 chữ rồi lật trang khác', 'Vứt vở mới mua ra sân mưa'],
               'Tiết kiệm từng trang giấy là bảo vệ rừng xanh và tôn trọng chuỗi lao động của hàng trăm người!', 'Tiết kiệm giấy từ lòng biết ơn'),
            _q(3, 12, 'application', 'Chú bảo vệ trường em sáng nào cũng có mặt từ 6 giờ sáng mở cổng và tối muộn mới khóa cửa ra về. Khi thấy cổng trường đã khóa muộn lúc bố chưa kịp đón, em nên ứng xử thế nào với chú?', 'Lễ phép ngồi gọn ở phòng trực bảo vệ nhờ chú giữ giúp và yên tâm đợi bố đến đón, khi về chào cảm ơn chú chu đáo', ['Chạy trèo qua hàng rào cổng sắt ra ngoài một mình', 'La hét đập cổng đòi chú mở khóa cho chạy ra đường lớn', 'Chui ra bãi xe nghịch khóa xe'],
               'Tin tưởng và hợp tác lịch sự với chú bảo vệ giúp đảm bảo an toàn tuyệt đối cho chính em.', 'Lịch sự với chú bảo vệ'),
            _q(3, 13, 'advanced', 'Một bác thợ mộc đóng bàn ghế cho trường học mỗi ngày làm việc 8 giờ. Trong 1 tuần làm việc 5 ngày, bác đóng được 10 bộ bàn ghế học sinh (mỗi ngày làm việc đều đặn như nhau). Hỏi trung bình bác cần bao nhiêu giờ lao động để hoàn thành xong 1 bộ bàn ghế mới cho lớp em ngồi?', '4 giờ lao động', ['2 giờ lao động', '5 giờ lao động', '8 giờ lao động'],
               'Tổng thời gian = 8 x 5 = 40 giờ; đóng 10 bộ -> mỗi bộ cần 40 : 10 = 4 giờ lao động miệt mài!', 'Tính công sức làm bàn ghế'),
            _q(3, 14, 'advanced', 'Vì sao tục ngữ Việt Nam có câu: "Tay làm hàm nhai, tay quai miệng trễ" và "Ai ơi bưng bát cơm đầy / Dẻo thơm một hạt đắng cay muôn phần"?', 'Khuyên con người phải chăm chỉ lao động mới có cuộc sống ấm no, đồng thời nhắc ta biết ơn sâu sắc nỗi nhọc nhằn của người làm ra hạt gạo', ['Vì tay người luôn dài hơn miệng', 'Vì ăn cơm cần phải ăn thật nhanh', 'Vì chỉ nghề nông mới cần lao động'],
               'Ca dao tục ngữ Việt Nam luôn đề cao giá trị lao động và đạo lí uống nước nhớ nguồn.', 'Ca dao về lao động'),
            _q(3, 15, 'advanced', 'Có quan điểm sai lầm rằng: "Học sinh lớp 2 chưa đi làm kiếm tiền nên chưa phải người lao động và chẳng cần làm việc gì". Em phản biện ý kiến này thế nào?', 'Học tập tốt và tự giác làm các việc nhà, trực nhật lớp vừa sức chính là "lao động của tuổi nhỏ" rèn luyện thói quen siêng năng để tương lai góp ích cho xã hội', ['Đúng rồi, trẻ em chỉ cần ăn ngủ chơi thôi', 'Đúng rồi, làm việc nhà là việc riêng của bố mẹ', 'Chỉ khi nào có lương mới gọi là lao động'],
               'Chăm học và phụ việc vừa sức giúp em rèn phẩm chất cần cù quý báu từ thuở thiếu thời.', 'Lao động vừa sức của bé'),
        ]
    ))

    # BÀI 4: Bảo quản đồ dùng học tập và lớp học
    lessons.append(make_lesson(
        'daoduc2-c1', 'daoduc2-b04', 'Bài 4. Bảo quản Đồ dùng Học tập và Tài sản Lớp học', 4,
        'Nâng cao ý thức giữ gìn sách vở cá nhân, bảo vệ bàn ghế, bảng lớp, cây xanh và thiết bị dạy học chung của lớp',
        ['Bảo quản đồ học tập', 'Giữ gìn bàn ghế lớp học', 'Ý thức tài sản chung'],
        [
            _q(4, 1, 'basic', 'Những tài sản chung nào trong lớp học mà mỗi học sinh lớp 2 đều phải chung tay giữ gìn cẩn thận?', 'Bàn ghế học sinh, bảng lớp, phấn viết, máy chiếu/tivi, quạt đèn, tủ sách lớp, chậu cây và cửa sổ lớp học', ['Chỉ riêng chiếc cặp sách đeo trên vai mình', 'Chỉ hộp bút màu của cá nhân', 'Đồ chơi đặt ở nhà riêng'],
               'Tài sản lớp học phục vụ cho cả tập thể hàng chục bạn trong nhiều năm học liên tiếp.', 'Nhận biết tài sản lớp học',
               fig=table_fig('Bảo quản Tài sản Chung', ['Tài sản', 'Cách giữ gìn đúng'], [['Bàn ghế gỗ', 'Không vẽ, khắc tên'], ['Bảng và phấn', 'Lau nhẹ, giữ phấn'], ['Tủ sách lớp', 'Đọc xong xếp gọn'], ['Quạt và đèn', 'Tắt khi ra khỏi lớp']])),
            _q(4, 2, 'basic', 'Hành động nào sau đây GÂY HƯ HỎNG tài sản chung của lớp học cần tuyệt đối tránh?', 'Dùng bút xóa, bút dạ hoặc đầu compa khắc vẽ nguệch ngoạc lên mặt bàn gỗ và tường lớp', ['Kê lại ngay ngắn bàn ghế cuối buổi học', 'Lau sạch bảng đen bằng khăn ẩm nhẹ nhàng', 'Tắt quạt điện khi cả lớp ra sân tập thể dục'],
               'Vẽ bậy khắc tên lên mặt bàn làm mất mĩ quan lớp học và hỏng lớp sơn gỗ bảo vệ bàn.', 'Tránh phá hoại bàn ghế'),
            _q(4, 3, 'basic', 'Khi sử dụng sách truyện ở "Thư viện góc lớp", quy tắc mượn và trả sách đúng chuẩn là gì?', 'Giữ tay sạch trước khi mở trang, không gấp góc đánh dấu trang, đọc xong đặt nhẹ nhàng trả đúng kệ quy định', ['Vừa ăn bánh tráng dầu mỡ vừa lật trang sách', 'Xé tranh ảnh đẹp trong truyện mang về nhà dán vở', 'Quẳng sách bừa bãi lên nóc tủ'],
               'Giữ gìn sách thư viện giúp hàng trăm bạn khác đều được đọc những quyển sách sạch đẹp như mới.', 'Văn hóa thư viện lớp'),
            _q(4, 4, 'basic', 'Sau khi cả lớp ra sân chào cờ đầu tuần hoặc ra về cuối buổi chiều, người học sinh có trách nhiệm sẽ kiểm tra việc gì trước khi ra khỏi phòng?', 'Kiểm tra tắt hết các công tắc đèn điện, quạt trần, đóng gọn cửa sổ tránh mưa hắt và thu dọn rác dưới ngăn bàn mình', ['Chạy ùa ra trước bỏ mặc quạt đèn chạy suốt trưa', 'Mở tung cửa sổ khi trời sắp mưa bão', 'Đá đổ hết ghế ngồi của bàn bên cạnh'],
               'Tắt thiết bị điện khi không sử dụng vừa bảo vệ đồ bền lâu vừa tiết kiệm điện cho nhà trường.', 'Tiết kiệm điện lớp học'),
            _q(4, 5, 'basic', 'Để bộ đồ dùng thực hành Toán và Thủ công lớp 2 (que tính, thước, bảng con, bộ ghép hình) không bị rơi mất mảnh ghép nào, em cần làm gì sau mỗi tiết học?', 'Kiểm đếm đủ các mảnh ghép, lau sạch bảng con bằng giẻ lau và xếp gọn nắp hộp cài chặt cất vào ngăn quy định', ['Trộn lẫn tất cả đồ dùng của mình vào cặp bạn bên cạnh', 'Ném phấn trắng xuống gầm bàn', 'Quăng hộp đồ dùng lăn lóc ngoài hành lang'],
               'Kiểm đếm và đóng chặt hộp đồ dùng ngay cuối tiết giúp em không bao giờ bị thiếu đồ ở tiết sau.', 'Cất gọn hộp thực hành'),
            _q(4, 6, 'basic', 'Nếu vô tình làm gãy thanh gỗ tựa lưng ghế hoặc làm bung bản lề cánh cửa tủ lớp học, em cần làm gì ngay?', 'Trung thực báo ngay với cô giáo chủ nhiệm để thầy cô nhờ bác thợ sửa chữa nhà trường gia cố an toàn kịp thời', ['Giấu nhẹm đi mặc kệ bạn khác ngồi vào bị ngã đau', 'Bẻ nốt cho gãy hẳn ra làm gậy chơi', 'Đổ lỗi cho lớp khác sang phá'],
               'Phát hiện và báo hỏng sớm giúp sửa chữa an toàn, phòng tránh tai nạn kẹp tay hay gãy ghế bất ngờ.', 'Báo hỏng kịp thời'),
            _q(4, 7, 'application', 'Bạn Minh hay có thói quen dùng chiếc thước kẻ nhựa của mình đập chan chát xuống mặt bàn gỗ làm nhịp hát giờ giải lao, khiến thước bị sứt mẻ nhiều chỗ và mặt bàn xước. Nếu ngồi cạnh Minh, em nhắc bạn sao cho khéo?', 'Nhắc nhẹ: "Minh ơi dùng thước đập bàn dễ gãy thước sứt mẻ mất vạch số đo và làm xước mặt bàn lớp mình đấy, tụi mình vỗ tay theo nhịp vui hơn nhé!"', ['Khen Minh gõ trống bằng thước cực hay rồi lấy thước mình gõ chung', 'Giật bẻ gãy đôi chiếc thước của Minh', 'Mặc kệ không nói gì cả'],
               'Gợi ý giải pháp thay thế tích cực (vỗ tay) vừa giữ được đồ dùng vừa giữ tình bạn vui vẻ.', 'Khéo léo nhắc nhở bạn'),
            _q(4, 8, 'application', 'Trong lớp 2C có 16 bộ bàn ghế đôi cho học sinh ngồi. Sau đợt thi đua "Lớp học Xanh – Sạch – Đẹp", tổ 1 giữ nguyên 4 bộ sạch đẹp, tổ 2 giữ 4 bộ, tổ 3 giữ 4 bộ, riêng tổ 4 có 1 bàn lỡ bị vết mực nhỏ nên các bạn tự mang khăn ẩm lau sạch lại ngay. Hỏi lúc kiểm tra cuối tuần lớp 2C có bao nhiêu bộ bàn ghế sạch đẹp đạt chuẩn?', 'Cả 16 bộ bàn ghế đều sạch đẹp đạt chuẩn!', ['12 bộ bàn ghế', '15 bộ bàn ghế', '14 bộ bàn ghế'],
               'Tổ 4 đã chủ động khắc phục lau sạch vết mực ngay nên cả 4 + 4 + 4 + 4 = 16 bộ bàn ghế đều đạt chuẩn!', 'Chủ động khắc phục sự cố'),
            _q(4, 9, 'application', 'Thứ Sáu cuối tuần, cô giáo kiểm tra góc học tập và hộp đồ dùng 4 tổ. Kết quả số học sinh giữ gìn đủ đồ dùng học tập suốt tháng 10 được vẽ ở biểu đồ dưới đây. Hỏi cả 4 tổ có tổng cộng bao nhiêu bạn giữ đủ đồ dùng không mất món nào?', '34 bạn (9 + 8 + 9 + 8)', ['30 bạn', '32 bạn', '36 bạn'],
               '9 + 8 + 9 + 8 = 34 bạn giữ đủ nguyên vẹn toàn bộ đồ dùng học tập!', 'Đọc biểu đồ thi đua',
               fig=bars_fig('Học sinh giữ đủ đồ dùng tháng 10', ['Tổ 1', 'Tổ 2', 'Tổ 3', 'Tổ 4'], [9, 8, 9, 8], 'bạn')),
            _q(4, 10, 'application', 'Giờ ra chơi trời nổi gió mạnh làm cửa kính lớp học đập mạnh kêu cạch cạch rất dễ vỡ. Em đang ở trong lớp cần làm gì?', 'Cài chốt móc giữ cánh cửa sổ lại cẩn thận (hoặc nhờ thầy cô đóng bớt cửa tránh va đập) để bảo vệ kính không bị gió thổi vỡ', ['Đứng nhìn cửa đập vào tường cho vui mắt', 'Đẩy mạnh thêm cho cánh cửa đập to hơn', 'Mở toang tất cả các cửa còn lại'],
               'Chủ động cài chốt cửa khi có gió lớn bảo vệ an toàn cho lớp học và tránh mảnh kính vỡ nguy hiểm.', 'Bảo vệ cửa sổ khi gió lớn'),
            _q(4, 11, 'application', 'Bạn Lan phát hiện một bạn lớp mình lấy phấn màu của cô giáo ở bàn giáo viên mang ra vẽ bậy khắp hành lang tường trắng. Lan nên khuyên bạn ấy thế nào?', 'Khuyên bạn dừng tay ngay, lấy khăn ẩm lau sạch vết phấn trên tường và đặt lại hộp phấn ngay ngắn về khay của cô để giữ trường sạch đẹp', ['Xin thêm hai viên phấn vẽ tiếp cùng bạn cho đẹp hành lang', 'Chụp ảnh cười trêu rồi bỏ chạy', 'Ném hộp phấn xuống sân trường'],
               'Phấn viết bảng dành cho giảng dạy; giữ sạch tường lớp giúp không gian trường học luôn sáng sủa văn minh.', 'Giữ sạch tường hành lang'),
            _q(4, 12, 'application', 'Khi viết xong bài tập bằng bút mực (lớp 2 bắt đầu tập viết bút mực), thói quen bảo quản bút nào giúp ngòi bút không bị cong gãy và không dây mực bẩn ra vở và áo quần?', 'Vẩy nhẹ mực thừa vào giấy thấm (không vẩy ra sàn), đậy chặt nắp bút ngay sau khi viết xong và đặt nằm gọn trong hộp bút', ['Vẩy mạnh bút mực tung tóe lên tường và áo bạn bên cạnh', 'Cắm đầu ngòi bút mạnh xuống mặt bàn cho thử độ cứng', 'Ngậm đuôi bút và quên đóng nắp cất thẳng vào cặp'],
               'Bảo quản bút mực sạch sẽ giúp vở luôn sạch đẹp không nhòe mực và chữ viết ngày càng nắn nót!', 'Bảo quản bút mực lớp 2'),
            _q(4, 13, 'advanced', 'Mỗi quyển sách giáo khoa nếu được giữ gìn sạch đẹp không viết vẽ bẩn vào sách thì có thể dùng lại được cho ít nhất 4 thế hệ em học sinh khóa sau. Nếu một tủ sách quyên góp của lớp 2 có 30 quyển sách giữ sạch đẹp truyền qua 3 khóa học sinh nữa, tổng cộng có bao nhiêu lượt bạn nhỏ được dùng bộ sách đó (tính cả em năm nay)?', '120 lượt học sinh (30 x 4 lượt)', ['90 lượt học sinh', '60 lượt học sinh', '34 lượt học sinh'],
               'Em dùng 1 khóa + truyền lại 3 khóa = 4 khóa học; 30 quyển x 4 lượt = 120 lượt học sinh hưởng lợi!', 'Giá trị tái sử dụng sách'),
            _q(4, 14, 'advanced', 'Vì sao giữ gìn đồ dùng học tập và tài sản lớp học lại có mối liên hệ chặt chẽ với việc bảo vệ môi trường xanh trên Trái Đất?', 'Vì giấy vở và bàn gỗ làm từ cây rừng tự nhiên; giữ gìn dùng bền lâu giúp giảm chặt cây và giảm rác thải nhựa ra môi trường', ['Vì giữ gìn bàn ghế giúp cây tự mọc trong lớp học', 'Vì giấy vở không liên quan gì đến cây xanh', 'Vì bút nhựa không bao giờ thành rác'],
               'Tiết kiệm đồ dùng là hành động sống xanh thiết thực bảo vệ tài nguyên thiên nhiên Trái Đất!', 'Bảo quản đồ dùng và Sống xanh'),
            _q(4, 15, 'advanced', 'Giữa khẩu hiệu "Của chung là của tập thể – Mỗi người giữ một chút sẽ bền đẹp mãi" và suy nghĩ "Của công chẳng phải của riêng nhà mình nên hỏng mặc kệ", khác biệt lớn nhất nằm ở đâu?', 'Nằm ở ý thức trách nhiệm công dân và lòng tự trọng: người văn minh biết coi trọng lợi ích tập thể như chính ngôi nhà thân yêu của mình', ['Không có sự khác biệt nào cả', 'Đều đúng tùy theo tâm trạng từng ngày', 'Chỉ người giàu mới cần giữ đồ riêng'],
               'Ý thức giữ gìn tài sản chung chính là thước đo độ trưởng thành của học sinh hiện đại.', 'Ý thức trách nhiệm công dân'),
        ]
    ))

    # BÀI 5: Nhận lỗi và sửa lỗi
    lessons.append(make_lesson(
        'daoduc2-c2', 'daoduc2-b05', 'Bài 5. Nhận lỗi và Sửa lỗi', 5,
        'Nhận thức được ai cũng có lúc vô tình mắc lỗi; biết dũng cảm nhận lỗi chân thành và có hành động sửa lỗi cụ thể',
        ['Dũng cảm nhận lỗi', 'Chân thành sửa sai', 'Không đổ lỗi người khác'],
        [
            _q(5, 1, 'basic', 'Khi em vô tình mắc một lỗi sai (như làm đổ nước ướt vở bạn, lỡ đi học muộn hay quên làm bài tập), thái độ đúng đắn nhất là gì?', 'Dũng cảm thừa nhận lỗi của mình, chân thành nói lời xin lỗi và nhanh chóng khắc phục sửa sai', ['Tìm cách giấu nhẹm hoặc nói dối để tránh bị nhắc nhở', 'Đổ tội cho bạn bên cạnh hoặc cho thời tiết', 'Cáu gắt giận dỗi ngược lại người bị hại'],
               'Dám nhận lỗi cần lòng can đảm; sửa lỗi giúp ta tiến bộ trưởng thành hơn sau mỗi lần vấp ngã.', 'Thái độ đúng khi mắc lỗi',
               fig=table_fig('Quy trình 3 Bước Sửa lỗi', ['Bước', 'Hành động cụ thể'], [['1. Dũng cảm nhận', 'Nhận đúng việc sai'], ['2. Xin lỗi thật lòng', 'Nhìn người liên quan'], ['3. Hành động sửa', 'Khắc phục, sửa ngay']])),
            _q(5, 2, 'basic', 'Vì sao người dám nhận lỗi khi làm sai lại được mọi người kính trọng và yêu quý hơn người tìm cách đổ lỗi cho hoàn cảnh?', 'Vì đó là người trung thực, có trách nhiệm và đáng tin cậy để mọi người yên tâm kết bạn, giao việc', ['Vì người nhận lỗi không bao giờ mắc lỗi nữa', 'Vì người đổ lỗi luôn nói hay hơn', 'Vì người nhận lỗi luôn được cho tiền'],
               'Sự trung thực và tinh thần chịu trách nhiệm luôn chiếm được niềm tin yêu sâu sắc của thầy cô và bạn bè.', 'Giá trị của lòng dũng cảm'),
            _q(5, 3, 'basic', 'Hành động nào dưới đây KHÔNG PHẢI là nhận lỗi thật sự mà chỉ là "xin lỗi cho xong chuyện"?', 'Miệng nói "Em xin lỗi ạ" nhưng ngay hôm sau vẫn lặp lại y hệt lỗi cũ mà không cố gắng sửa đổi chút nào', ['Nói xin lỗi kèm nhặt lại sách vở giúp bạn', 'Ghi nhớ khuyết điểm để không tái phạm lần sau', 'Tự nguyện làm bù lại phần bài tập bị thiếu'],
               'Giá trị cao nhất của lời nhận lỗi nằm ở sự thay đổi hành động tích cực sau đó.', 'Phân biệt nhận lỗi thật sự'),
            _q(5, 4, 'basic', 'Khi thấy em nhỏ hay bạn thân của mình lỡ mắc lỗi sai nhưng đang sợ sệt rụt rè không dám nói, em nên khuyên bạn thế nào?', 'Động viên bạn bình tĩnh dũng cảm nhận lỗi thật với bố mẹ/cô giáo và cùng bạn tìm cách khắc phục nhẹ nhàng nhất', ['Xúi bạn nói dối trốn tội cho an toàn', 'Chê cười dọa nạt làm bạn càng sợ hơn', 'Giúp bạn đổ lỗi sang một bạn khác vắng mặt'],
               'Ủng hộ bạn dũng cảm sống thật là giúp bạn giữ vững nhân cách tốt đẹp.', 'Khích lệ bạn nhận lỗi'),
            _q(5, 5, 'basic', 'Ai trong cuộc sống có thể có lúc vô tình mắc khuyết điểm hay sai sót nhỏ?', 'Bất kì ai cũng có thể đôi lúc sơ ý mắc sai sót, quan trọng nhất là biết nhận ra lỗi và chân thành sửa chữa để tốt hơn', ['Chỉ những bạn học kém mới từng mắc lỗi', 'Người lớn không bao giờ làm sai việc gì', 'Chỉ trẻ em dưới 6 tuổi mới có lỗi'],
               '"Nhân vô thập toàn" – không ai hoàn hảo cả đời, người bản lĩnh là người biết học từ sai lầm.', 'Hiểu đúng về sai sót'),
            _q(5, 6, 'basic', 'Lợi ích tuyệt vời đối với bản thân em sau khi dũng cảm thú nhận một lỗi nhỏ mình trót gây ra là gì?', 'Tâm trạng nhẹ nhõm thanh thản hết lo âu, nhận được sự tha thứ chỉ bảo và rút ra bài học kinh nghiệm quý giá', ['Bị mọi người ghét bỏ mãi mãi không chơi cùng', 'Mất hết tất cả đồ dùng học tập', 'Ngày càng hay nói dối giỏi hơn'],
               'Thừa nhận sự thật giải phóng ta khỏi gánh nặng sợ hãi và mở đường cho sự tiến bộ.', 'Tâm lí sau khi nhận lỗi'),
            _q(5, 7, 'application', 'Trên đường đi học, bạn Nam vô tình vung chiếc ô gấp trúng làm rơi hộp sữa mới mua trên tay em bé lớp 1 xuống đất vỡ nắp. Xung quanh không có thầy cô. Nam nên làm gì ngay?', 'Dừng lại ngay lập tức, xin lỗi em bé chân thành, giúp nhặt hộp sữa hỏng bỏ vào thùng rác sạch sẽ và dẫn em báo cô giáo (hoặc nhường hộp sữa của mình cho em)', ['Chạy thật nhanh giả vờ như không phải mình đụng trúng', 'Mắng ngược lại em bé sao đi đứng không nhìn đường', 'Cười rồi bước tiếp'],
               'Chịu trách nhiệm ngay cả khi không có người lớn giám sát là đỉnh cao của sự tự trọng!', 'Tự giác nhận lỗi ở sân'),
            _q(5, 8, 'application', 'Trong giờ Mĩ thuật, Hoa mượn cây bút lông màu xanh của Mai nhưng lỡ làm tòe hết đầu lông bút không vẽ nét nhỏ được nữa. Cách sửa lỗi trọn vẹn nhất của Hoa là gì?', 'Thành thật xin lỗi Mai về sự sơ ý của mình và xin phép bố mẹ mua đền tặng lại Mai một cây bút lông màu xanh mới nguyên vẹn', ['Lén đổi cây bút hỏng của mình lấy cây bút mới trong hộp của Tú', 'Trả lén vào hộp của Mai không nói câu nào', 'Bảo Mai là bút cũ vốn đã hỏng từ trước'],
               'Bồi hoàn tổn thất do mình vô ý gây ra giúp giữ trọn chữ tín trong tình bạn.', 'Sửa lỗi làm hỏng đồ bạn'),
            _q(5, 9, 'application', 'Bạn Tuấn hứa với mẹ sẽ không xem tivi quá giờ nhưng mải mê hoạt hình quá mất 30 phút nên chưa kịp làm bài tập Toán. Khi mẹ đi làm về hỏi, Tuấn nên xử lí thế nào?', 'Thành thật nhận lỗi với mẹ là con đã mải xem quá giờ, xin lỗi mẹ và ngồi ngay vào bàn học nghiêm túc làm đủ bài tập bù lại', ['Nói dối mẹ là hôm nay cô giáo không giao bài tập nào', 'Tắt tivi nhanh rồi giả vờ nằm ngủ mệt', 'Đổ tại đồng hồ trong nhà chạy sai giờ'],
               'Nhận lỗi với cha mẹ và lập tức bắt tay sửa sai chứng tỏ sự trưởng thành đáng khen.', 'Nhận lỗi và sửa sai ở nhà'),
            _q(5, 10, 'application', 'Trong phong trào "Mỗi tuần một tiến bộ" của lớp 2B, số bạn từng quên đồ dùng hoặc nói chuyện riêng nhưng đã tự giác nhận lỗi và sửa hẳn hoàn toàn không tái phạm trong 4 tuần được ghi lại như biểu đồ. Hỏi Tuần 4 có bao nhiêu bạn tiến bộ vượt bậc?', '14 bạn (tăng mạnh từ 4 bạn ở Tuần 1 lên 14 bạn ở Tuần 4)', ['6 bạn', '9 bạn', '4 bạn'],
               'Biểu đồ cho thấy phong trào sửa lỗi tiến bộ đều qua từng tuần: 4 -> 6 -> 9 -> 14 bạn!', 'Đọc biểu đồ tiến bộ sửa lỗi',
               fig=bars_fig('Học sinh sửa hẳn lỗi cũ lớp 2B', ['Tuần 1', 'Tuần 2', 'Tuần 3', 'Tuần 4'], [4, 6, 9, 14], 'bạn')),
            _q(5, 11, 'application', 'Nếu một bạn trong lớp chân thành đến trước mặt em nói: "Hôm qua tớ lỡ hiểu nhầm nói nặng lời với cậu, cho tớ xin lỗi nhé!", em nên đáp lại thế nào?', 'Vui vẻ bắt tay mỉm cười bảo bạn "Không sao đâu, tụi mình hiểu nhau là vui rồi!" để tha thứ và tiếp tục chơi hòa thuận', ['Hất tay bạn ra bảo tớ ghim cậu suốt đời', 'Bắt bạn phải mua quà tạ lỗi thật to mới tha', 'Chụp ảnh bạn xin lỗi đi khoe khắp lớp'],
               'Biết nhận lỗi đã quý, biết rộng lòng tha thứ cho người sửa lỗi còn cao đẹp hơn nữa!', 'Đón nhận lời xin lỗi'),
            _q(5, 12, 'application', 'Khi chơi đá bóng trong sân trường (nơi cấm đá bóng gần cửa kính), nhóm bạn Minh lỡ sút mạnh làm nứt nhẹ một ô cửa kính tầng 1. Cách ứng xử đúng đắn của cả nhóm là gì?', 'Cả nhóm cùng dũng cảm lên văn phòng báo thật với thầy hiệu trưởng/chú bảo vệ, nhận lỗi chơi sai quy định và cam kết chỉ đá bóng ở sân bãi quy định', ['Cả nhóm chạy tản ra giả vờ đang đọc sách ở gốc cây', 'Đổ thừa tại quả bóng tự bay vào kính', 'Nhờ một bạn nhỏ nhất nhóm đứng ra nhận tội thay cả đám'],
               'Dám làm dám chịu trách nhiệm tập thể là phẩm chất anh hùng chân chính của học sinh lớp 2.', 'Trách nhiệm tập thể'),
            _q(5, 13, 'advanced', 'Bạn An đặt ra quy tắc kiểm điểm bản thân: cứ 1 lần quên hoàn thành bài phải viết 1 bảng kế hoạch tự nhắc nhở, và tự cộng 2 điểm thưởng mỗi tuần không mắc lại lỗi đó. Trong 4 tuần liên tiếp, tuần 1 An lỡ quên 1 lần nhưng cả 3 tuần sau An đều giữ vững không lặp lại lỗi cũ. Hỏi cuối tháng An tích lũy được bao nhiêu điểm thưởng sửa lỗi?', '6 điểm thưởng (3 tuần sau x 2 điểm)', ['2 điểm thưởng', '4 điểm thưởng', '8 điểm thưởng'],
               'Tuần 1 sửa lỗi xong, 3 tuần liên tiếp sau giữ vững kỉ luật: 3 x 2 = 6 điểm thưởng tiến bộ!', 'Bài toán rèn luyện bản thân'),
            _q(5, 14, 'advanced', 'Vì sao ông cha ta thường dạy: "Đánh kẻ chạy đi không ai đánh người chạy lại"?', 'Khuyên mọi người biết mở lòng bao dung tha thứ cho những ai đã biết hối hận, dũng cảm quay lại nhận lỗi và quyết tâm sửa sai làm người tốt', ['Vì người chạy đi chạy nhanh hơn nên dễ đánh hơn', 'Vì không cần quan tâm đến ai chạy lại', 'Khuyên người mắc lỗi cứ bỏ chạy thật xa'],
               'Tình nhân ái và lòng vị tha tạo cơ hội cho mọi người biết quay đầu sửa lỗi vươn lên.', 'Ý nghĩa câu tục ngữ'),
            _q(5, 15, 'advanced', 'Giữa hai tình huống: (A) Làm bài sai nhưng dũng cảm tự sửa lại sau khi nghe cô giảng và (B) Sợ mất mặt nên lén sửa đáp án đúng vào bài cũ rồi bảo cô chấm nhầm. Điều nào dẫn đến giá trị thật sự lâu dài?', 'Tình huống (A): vì nhận sai giúp em hiểu bản chất kiến thức và giữ trọn nhân phẩm trung thực không tì vết', ['Tình huống (B): vì được thêm điểm 10 ngay lập tức', 'Cả (A) và (B) đều giống hệt nhau', 'Không tình huống nào tốt cả'],
               'Trung thực trong việc nhận lỗi rèn giũa tâm hồn trong sáng và kiến thức vững chắc thật sự.', 'Bản lĩnh trước sai sót'),
        ]
    ))

    # BÀI 6: Giữ lời hứa
    lessons.append(make_lesson(
        'daoduc2-c2', 'daoduc2-b06', 'Bài 6. Giữ Lời hứa', 6,
        'Hiểu giá trị của chữ tín và biết cân nhắc kĩ trước khi hứa, luôn cố gắng thực hiện đúng điều đã hứa với người khác',
        ['Giữ lời hứa', 'Nói đi đôi với làm', 'Xây dựng lòng tin'],
        [
            _q(6, 1, 'basic', '"Giữ lời hứa" có nghĩa là gì trong cuộc sống hàng ngày?', 'Thực hiện đúng điều mình đã nói, đã cam kết hoặc đã hẹn với người khác một cách nghiêm túc và đúng thời hạn', ['Hứa thật nhiều cho vui miệng rồi quên sạch ngay sau đó', 'Chỉ làm điều mình thích còn điều đã hứa thì bỏ qua', 'Hứa giúp bạn nhưng lại nhờ người khác làm thay cho qua'],
               'Giữ lời hứa là nền tảng xây dựng chữ tín, khiến lời nói của em có trọng lượng và giá trị.', 'Khái niệm Giữ lời hứa',
               fig=table_fig('Người Giữ Chữ Tín', ['Nguyên tắc', 'Thực hiện cụ thể'], [['Trước khi hứa', 'Nghĩ kĩ khả năng làm'], ['Khi đã hứa', 'Cố gắng làm đúng hẹn'], ['Nếu gặp trở ngại', 'Báo trước, xin lỗi'], ['Kết quả đẹp', 'Được tin yêu nhiều']])),
            _q(6, 2, 'basic', 'Trước khi nhận lời hứa một việc gì đó với bạn bè hoặc bố mẹ, bước suy nghĩ quan trọng nhất em cần làm là gì?', 'Cân nhắc kĩ xem việc đó có đúng đắn, an toàn và nằm trong khả năng mình thực hiện được không rồi mới hứa', ['Hứa bừa ngay lập tức không cần nghĩ để lấy lòng trước', 'Hứa những việc quá nguy hiểm trái nội quy', 'Hứa xong để đó tính sau'],
               '"Hứa ít làm nhiều" – chỉ hứa những việc chính đáng và chắc chắn mình cố gắng làm được!', 'Suy nghĩ kĩ trước khi hứa'),
            _q(6, 3, 'basic', 'Hành động nào sau đây thể hiện bạn học sinh lớp 2 BIẾT GIỮ LỜI HỨA?', 'Bạn Lan hứa cho Mai mượn quyển truyện tranh vào sáng thứ Hai và Lan đã cất sẵn vào cặp từ tối Chủ nhật để mang đúng hẹn', ['Bạn Nam hẹn 3 giờ chiều sang học nhóm nhưng mải chơi điện tử quên mất tới tận tối', 'Bạn Tí hứa với cô giáo làm đủ bài tập nhưng sáng hôm sau lại để vở trống trơn', 'Bạn Hùng hứa trả cây thước mượn từ tháng trước đến nay vẫn chưa trả'],
               'Chuẩn bị sẵn từ hôm trước để thực hiện trọn vẹn lời hứa chứng tỏ bạn Lan cực kì đáng tin cậy.', 'Gương giữ lời hứa'),
            _q(6, 4, 'basic', 'Nếu vì một lí do bất khả kháng ngoài ý muốn (như đột ngột bị sốt ốm hoặc trời mưa bão lớn) khiến em không thể tới đúng giờ đã hẹn với bạn, em nên làm gì?', 'Nhờ bố mẹ gọi điện báo tin trước cho bạn biết sớm nhất có thể, xin lỗi bạn và hẹn lại một thời gian khác phù hợp', ['Im lặng ở nhà mặc kệ bạn đứng đợi dưới nắng mưa hàng tiếng', 'Tắt luôn điện thoại giả vờ không có chuyện gì', 'Trách ngược lại sao bạn lại hẹn vào ngày mưa'],
               'Thông báo kịp thời và hẹn lại rõ ràng thể hiện sự tôn trọng thời gian của người khác dù gặp sự cố.', 'Xử lí khi gặp trở ngại'),
            _q(6, 5, 'basic', 'Điều gì sẽ xảy ra nếu một người thường xuyên hứa suông mà không bao giờ thực hiện?', 'Mọi người sẽ dần mất hết lòng tin, không còn ai muốn hợp tác, giao việc hay tin vào những lời người đó nói nữa', ['Mọi người sẽ ngày càng quý mến ngưỡng mộ hơn', 'Sẽ được bầu làm lớp trưởng ngay lập tức', 'Lời nói sẽ ngày càng có giá trị hơn'],
               '"Một lần bất tín, vạn lần bất tin" – mất lòng tin rất dễ nhưng xây lại vô cùng khó khăn!', 'Hậu quả thất hứa'),
            _q(6, 6, 'basic', 'Nếu một bạn rủ em hứa cùng làm một việc XẤU hoặc NGUY HIỂM (như hứa giấu đồ của bạn khác hoặc hứa trốn học đi chơi), em có nên giữ lời hứa kiểu đó không?', 'Không bao giờ hứa ngay từ đầu; nếu trót lỡ miệng đồng ý thì phải dũng cảm dừng lại từ chối ngay vì không được tiếp tay cho việc sai trái', ['Phải giữ lời hứa làm việc xấu tới cùng mới là bạn tốt', 'Cứ làm lén lút miễn không ai biết', 'Rủ thêm nhiều bạn khác làm chung'],
               'Lời hứa chân chính luôn gắn với điều thiện lành, an toàn và đúng đắn!', 'Không hứa làm việc sai trái'),
            _q(6, 7, 'application', 'Bạn Minh hẹn gặp nhóm bạn ở thư viện lúc 8 giờ 30 sáng thứ Bảy (như đồng hồ chỉ giờ) để cùng làm báo tường. Để giữ trọn lời hứa đúng giờ, Minh nên rời nhà vào khoảng thời gian nào nếu đi bộ mất 15 phút?', 'Rời nhà lúc 8 giờ 10 hoặc muộn nhất là 8 giờ 15 sáng để có mặt đúng 8 giờ 30 không để nhóm chờ', ['8 giờ 30 mới bắt đầu xỏ giày ở cửa nhà', '9 giờ mới ung dung đi bộ sang thư viện', '7 giờ sáng đi rồi bỏ về trước 8 giờ'],
               'Tính trước thời gian di chuyển là kĩ năng thực tế giúp em luôn giữ đúng lời hứa giờ giấc!', 'Tính giờ để giữ hẹn',
               fig=fig_clock(8, 30, 'Giờ hẹn làm báo tường nhóm')),
            _q(6, 8, 'application', 'Mẹ đi chợ về mua hai chiếc bánh rán rất ngon. Bố dặn anh Tùng giữ 1 chiếc phần em út đi học về lúc 5 giờ chiều. Tùng hứa: "Vâng, con giữ phần em ạ!". Nhưng lúc đói bụng quá Tùng thèm ăn hết cả 2 chiếc. Nếu Tùng giữ lời hứa đúng đạo đức thì Tùng phải làm sao?', 'Kiềm chế cơn thèm, chỉ ăn đúng phần 1 chiếc của mình và bọc cất ngay ngắn 1 chiếc còn lại đợi em đi học về ăn ngon lành', ['Ăn hết luôn rồi bảo con mèo ăn vụng', 'Ăn một nửa chiếc của em rồi giấu một nửa', 'Đổ tại mẹ mua bánh ít quá'],
               'Làm chủ bản thân vượt qua cám dỗ nhỏ để giữ lời hứa với bố và nhường nhịn em nhỏ thật đáng khen!', 'Kiên định giữ lời hứa'),
            _q(6, 9, 'application', 'Lớp 2A có 4 bạn tham gia chiến dịch "7 ngày Giữ trọn Lời hứa" (thực hiện đủ 100% các việc đã tự hứa với cha mẹ và thầy cô). Biểu đồ ghi lại số việc làm tốt giữ lời hứa của 4 bạn trong tuần. Bạn nào thực hiện xuất sắc được nhiều việc nhất?', 'Bạn Hà (14 việc đã hứa đều làm tròn)', ['Bạn An (10 việc)', 'Bạn Bình (12 việc)', 'Bạn Chi (11 việc)'],
               'Cột của bạn Hà cao nhất đạt 14 việc đều giữ trọn chữ tín!', 'Đọc biểu đồ giữ lời hứa',
               fig=bars_fig('Việc làm giữ trọn lời hứa trong tuần', ['An', 'Bình', 'Chi', 'Hà'], [10, 12, 11, 14], 'việc')),
            _q(6, 10, 'application', 'Bạn Tú mượn quyển truyện tranh của Hùng và hứa thứ Tư trả. Đến sáng thứ Tư, Tú mới đọc được nửa quyển mà rất muốn đọc nốt. Tú làm thế nào để không mang tiếng thất hứa?', 'Sáng thứ Tư vẫn mang truyện tới lớp đưa đúng hẹn (hoặc gặp Hùng từ sáng xin phép lịch sự cho mượn thêm đến thứ Năm nếu Hùng đồng ý)', ['Im lặng giữ luôn quyển truyện ở nhà chờ đọc xong tuần sau mới đưa', 'Nói dối Hùng là quên mang cặp sách', 'Đem quyển truyện đó cho bạn khác mượn tiếp'],
               'Chủ động trao đổi rõ ràng đúng ngày hẹn thể hiện sự tôn trọng tuyệt đối lời hứa ban đầu!', 'Ứng xử khéo khi mượn đồ'),
            _q(6, 11, 'application', 'Khi mẹ ốm mệt, em hứa với mẹ: "Hôm nay con sẽ tự giác học bài xong trước 8 giờ tối và xếp gọn quần áo giúp mẹ nhé!". Đến tối cô bạn hàng xóm sang rủ em sang xem phim hoạt hình mới rất hay đúng 7 giờ. Em xử lí ra sao?', 'Từ chối khéo bạn: "Hôm nay mình đã hứa tự học và phụ giúp mẹ rồi, hẹn cậu cuối tuần rảnh mình cùng xem sau nhé!" và thực hiện trọn lời hứa với mẹ', ['Bỏ luôn việc học và quần áo chạy sang nhà bạn xem đến khuya', 'Quát mắng mẹ không cho mình đi chơi', 'Làm qua loa rồi ném đại quần áo vào gầm giường'],
               'Ưu tiên lời hứa đã cam kết thay vì chạy theo sở thích nhất thời là biểu hiện bản lĩnh tuyệt vời.', 'Ưu tiên giữ lời hứa'),
            _q(6, 12, 'application', 'Nếu một người bạn lớn tuổi hơn hay hứa suông để em giúp bạn ấy làm việc hộ nhưng sau đó bạn ấy thất hứa không trả ơn như đã nói, em rút ra bài học gì?', 'Nhắc nhẹ bạn lịch sự về lời đã hứa, đồng thời vẫn giữ chữ tín ở những việc chính đáng chứ không bắt chước thói thất hứa', ['Từ nay mình cũng thất hứa lại với tất cả mọi người cho công bằng', 'Đánh nhau với bạn ngay giữa sân trường', 'Nói xấu bạn trên mạng xã hội'],
               'Giữ chữ tín là phẩm chất tự thân của mình, không để hành vi xấu của người khác làm mình thay đổi tốt đẹp.', 'Giữ chữ tín bản thân'),
            _q(6, 13, 'advanced', 'Một nhóm bạn 5 người cam kết thực hiện "Hũ Tiết kiệm Sách": mỗi bạn hứa mỗi tháng đóng góp ít nhất 2 quyển truyện hay đã đọc xong vào tủ sách lớp. Sau 3 tháng học kì 1, cả 5 bạn đều giữ đúng lời hứa. Tổng số truyện tủ sách lớp nhận thêm được là bao nhiêu quyển?', '30 quyển truyện', ['15 quyển truyện', '25 quyển truyện', '10 quyển truyện'],
               '1 tháng cả nhóm = 5 x 2 = 10 quyển -> 3 tháng giữ trọn lời hứa = 10 x 3 = 30 quyển truyện hay!', 'Toán sức mạnh chữ tín'),
            _q(6, 14, 'advanced', 'Vì sao ông cha ta nhấn mạnh: "Nói chín thì nên làm mười / Nói mười làm chín kẻ cười người chê"?', 'Khuyên người ta chớ nên hứa hão phóng đại quá khả năng; hãy khiêm tốn hứa vừa phải và cố gắng làm thật tốt vượt mong đợi để giữ trọn uy tín', ['Vì số 9 luôn lớn hơn số 10', 'Vì không bao giờ được đếm tới số 10', 'Khuyên mọi người cứ nói nhiều gấp đôi việc làm'],
               'Làm tốt hơn cả điều đã hứa tạo nên sức hút tin cậy tuyệt vời ở mỗi con người.', 'Câu ca dao về chữ tín'),
            _q(6, 15, 'advanced', 'So sánh "Lời hứa bằng miệng" và "Lời cam kết tự hứa với chính bản thân mình" (như tự hứa mỗi ngày dậy sớm tập thể dục): Lời hứa với bản thân có quan trọng không?', 'Vô cùng quan trọng, vì nếu ngay cả lời hứa với chính mình em còn dễ dàng phá bỏ thì rất khó giữ được kỉ luật bản thân để thực hiện lời hứa lớn với mọi người', ['Không quan trọng, tự hứa thì muốn bỏ lúc nào cũng được', 'Chỉ lời hứa trước mặt thầy cô mới cần giữ', 'Không ai biết nên không cần làm'],
               'Giữ lời hứa với chính mình (Self-integrity) là gốc rễ tạo nên con người thành công và đáng kính!', 'Chữ tín với chính mình'),
        ]
    ))

    # BÀI 7: Chia sẻ với bạn gặp khó khăn
    lessons.append(make_lesson(
        'daoduc2-c2', 'daoduc2-b07', 'Bài 7. Chia sẻ với Bạn gặp Khó khăn', 7,
        'Nhận biết các hoàn cảnh khó khăn của bạn bè xung quanh và có hành động quan tâm, giúp đỡ thiết thực, tôn trọng bạn',
        ['Đồng cảm sẻ chia', 'Lá lành đùm lá rách', 'Giúp đỡ tôn trọng bạn'],
        [
            _q(7, 1, 'basic', 'Khi thấy một bạn trong lớp hoặc ngoài cộng đồng đang gặp hoàn cảnh khó khăn (như nhà bị bão lụt, người thân ốm nặng, thiếu sách vở hay bị thương tạm thời), thái độ nhân ái cần có là gì?', 'Đồng cảm, lắng nghe an ủi chân thành và sẵn lòng sẻ chia giúp đỡ bạn những việc vừa sức mình', ['Thờ ơ coi như không liên quan đến mình', 'Khoe khoang giàu có trước mặt để làm bạn tủi thân', 'Xa lánh không muốn ngồi cạnh hay chơi cùng bạn'],
               'Lòng nhân ái biết sẻ chia làm dịu bớt nỗi đau và tiếp thêm sức mạnh cho bạn vượt qua nghịch cảnh.', 'Lòng nhân ái sẻ chia',
               fig=table_fig('Sẻ chia với Bạn bè', ['Hoàn cảnh bạn', 'Việc giúp vừa sức'], [['Bạn bị đau chân', 'Xách cặp, dìu bạn đi'], ['Bạn nghỉ ốm', 'Chép bài, hỏi thăm'], ['Vùng bão lũ', 'Góp sách vở, áo ấm'], ['Khi giúp đỡ', 'Chân thành, tế nhị']])),
            _q(7, 2, 'basic', 'Bạn Nam không may bị trẹo chân phải bó bột vài tuần nên đi lại rất khó khăn. Khi Nam đi học lại, bạn bè trong lớp có thể giúp Nam việc gì thiết thực nhất?', 'Thay phiên xách hộ cặp sách lên cầu thang, dìu nhẹ Nam vào chỗ ngồi và lấy giúp nước uống trong giờ giải lao', ['Chạy thi xem ai chạy quanh bạn nhanh hơn', 'Rủ Nam chơi nhảy lò cò một chân', 'Lấy nạng chống của bạn giấu đi trêu đùa'],
               'Hỗ trợ thiết thực việc đi lại an toàn giúp bạn bị đau vẫn vui vẻ hòa nhập việc học.', 'Giúp bạn khi đau ốm'),
            _q(7, 3, 'basic', 'Trong phong trào "Kế hoạch nhỏ" hay "Áo ấm tặng bạn vùng cao" của nhà trường, em nên quyên góp những đồ dùng như thế nào?', 'Những quyển vở mới, sách giáo khoa sạch đẹp không rách nát, quần áo đã giặt sạch thơm gấp ngay ngắn và đồ dùng còn sử dụng tốt', ['Những chiếc áo rách thủng hoặc bẩn không giặt để vứt đi', 'Sách vở vẽ bậy rách mất hết nửa số trang', 'Đồ chơi hỏng gãy sắc nhọn'],
               'Của cho không bằng cách cho – gửi tặng đồ sạch đẹp thể hiện sự tôn trọng sâu sắc dành cho bạn nhận.', 'Chuẩn bị quà sẻ chia chuẩn'),
            _q(7, 4, 'basic', 'Câu tục ngữ Việt Nam nào ca ngợi tinh thần tương thân tương ái, giúp đỡ lẫn nhau lúc hoạn nạn khó khăn?', '"Lá lành đùm lá rách" và "Thương người như thể thương thân"', ['"Đèn nhà ai nấy rạng"', '"Việc ai nấy làm mặc kệ người khác"', '"Ăn cây táo rào cây sung"'],
               'Truyền thống đoàn kết thương yêu đùm bọc là sức mạnh văn hóa ngàn đời của dân tộc Việt Nam.', 'Tục ngữ về lòng nhân ái'),
            _q(7, 5, 'basic', 'Khi mang sách vở hay chiếc bánh chia sẻ cho một bạn có hoàn cảnh kém may mắn hơn mình, điều CẦN TRÁNH nhất trong lời nói và ánh mắt là gì?', 'Tránh thái độ thương hại bề trên, khoe khoang ồn ào hoặc nói năng cộc lốc làm bạn cảm thấy mặc cảm xấu hổ', ['Mỉm cười thân thiện coi bạn như người anh em ngang hàng', 'Trao tận tay nhẹ nhàng kín đáo', 'Chúc bạn học thật tốt và vui khỏe'],
               'Giúp đỡ đi kèm sự tế nhị bảo vệ lòng tự trọng của bạn mới là sự sẻ chia cao đẹp thực sự.', 'Tế nhị khi giúp bạn'),
            _q(7, 6, 'basic', 'Ngoài tiền bạc hay vật chất đồ dùng, chúng ta còn có thể chia sẻ giúp đỡ bạn gặp khó khăn bằng hình thức tinh thần quý giá nào?', 'Ở bên cạnh lắng nghe bạn tâm sự, giảng bài cho bạn theo kịp lớp, chơi cùng để bạn bớt cô đơn và động viên lời tích cực', ['Không có tiền thì không thể giúp được gì cả', 'Chỉ có người lớn mới giúp được tinh thần', 'Chê bạn yếu đuối không đáng chơi'],
               'Sự hiện diện, nụ cười và lời động viên ấm áp đôi khi quý giá hơn bất kì món quà vật chất nào!', 'Sẻ chia giá trị tinh thần'),
            _q(7, 7, 'application', 'Bạn Hà vừa trải qua trận lũ lụt ở quê làm ướt hỏng toàn bộ hộp bút chì màu và sách tập vẽ. Hôm nay trở lại lớp Hà ngồi thẫn thờ nhìn tiết Mĩ thuật. Bạn Mai ngồi cạnh có hộp 24 cây bút màu rất đẹp nên làm gì?', 'Đặt hộp 24 cây bút màu vào giữa mặt bàn và vui vẻ mời Hà: "Hà dùng chung bút màu với tớ nhé, tớ chia đôi ra cho hai đứa cùng tô thật đẹp!"', ['Ôm chặt hộp bút vào lòng sợ Hà làm mòn ngòi màu', 'Khoe với Hà là nhà mình mới mua bộ bút đắt tiền lắm', 'Bảo Hà đứng ngoài nhìn mình vẽ thôi'],
               'Chia sẻ ngay lúc bạn thiếu thốn giúp Hà quên đi nỗi buồn mất đồ và cảm nhận tình bạn ấm áp.', 'Chia sẻ trong tiết Mĩ thuật'),
            _q(7, 8, 'application', 'Trong lớp 2A có một bạn hoàn cảnh gia đình khó khăn phải mặc áo đồng phục cũ sờn hơn các bạn một chút nhưng luôn sạch sẽ gọn gàng. Một bạn mới chuyển vào lỡ miệng chê chiếc áo đó cũ kĩ. Em cần nói gì để bảo vệ bạn?', 'Nhắc bạn mới: "Áo bạn ấy tuy cũ nhưng sạch sẽ thơm tho và bạn học chăm ngoan lắm; chúng mình quý nhau ở tấm lòng chứ không chê quần áo!"', ['Gật đầu bảo đúng rồi bạn ấy nghèo lắm', 'Cười theo lời chê của bạn mới', 'Bảo bạn mặc áo cũ đừng đi học nữa'],
               'Bảo vệ bạn khỏi sự chê bai vật chất lan tỏa môi trường học đường nhân văn và công bằng.', 'Bảo vệ bạn khỏi định kiến'),
            _q(7, 9, 'application', 'Chiến dịch "Góp sách hay – Trao yêu thương" của khối 2 nhận được sự hưởng ứng nhiệt tình từ 3 lớp như biểu đồ dưới đây. Hỏi lớp 2C góp nhiều hơn lớp 2A bao nhiêu quyển sách?', '15 quyển sách (45 - 30 = 15)', ['10 quyển', '20 quyển', '5 quyển'],
               'Nhìn biểu đồ: 2C góp 45 quyển, 2A góp 30 quyển -> hơn 45 - 30 = 15 quyển.', 'Đọc biểu đồ quyên góp',
               fig=bars_fig('Quyên góp sách khối 2 tặng bạn', ['Lớp 2A', 'Lớp 2B', 'Lớp 2C'], [30, 35, 45], 'quyển')),
            _q(7, 10, 'application', 'Lớp 2D tổ chức đi thăm và tặng quà một bạn trong lớp bị ốm nằm viện 1 tuần. Khi vào phòng bệnh thăm bạn, cả nhóm cần lưu ý giữ nếp ứng xử nào?', 'Đi nhẹ nói khẽ không làm ồn các bệnh nhân xung quanh, hỏi thăm động viên bạn mau khỏe và kể chuyện vui nhẹ nhàng trong lớp không ở lại quá lâu làm bạn mệt', ['Chạy nhảy la hét ầm ĩ khắp hành lang bệnh viện', 'Cả 10 bạn cùng nói một lúc bắt bạn phải trả lời hết', 'Ăn vặt vứt rác ra phòng bệnh'],
               'Thăm người ốm văn minh tôn trọng không gian yên tĩnh nghỉ ngơi của bệnh viện.', 'Văn hóa thăm bạn bị ốm'),
            _q(7, 11, 'application', 'Mỗi buổi sáng Lan được mẹ cho 10 nghìn đồng bỏ ống heo đất tiết kiệm. Sau 2 tuần tiết kiệm được một khoản nhỏ, Lan muốn trích một phần ủng hộ quỹ "Bạn nghèo vượt khó" ở trường. Lan nên làm gì trước khi lấy tiền?', 'Nói rõ ý muốn tốt đẹp đó xin phép mẹ đồng ý rồi cùng mẹ mang đóng góp minh bạch cho cô giáo chủ nhiệm', ['Tự ý đập vỡ lợn đất giấu mẹ mang đi tiêu', 'Xin thêm thật nhiều tiền rồi giữ lại mua đồ chơi cho mình', 'Không cần xin phép mẹ cứ lấy lén ví của mẹ'],
               'Báo cáo và xin ý kiến cha mẹ khi dùng tiền tiết kiệm giúp việc thiện thêm minh bạch và được hướng dẫn đúng cách.', 'Thiện nguyện minh bạch'),
            _q(7, 12, 'application', 'Bạn Tú học chậm môn Đọc hơn các bạn vì gia đình chuyển vùng nhiều lần. Khi thấy Tú đọc còn vấp chữ và buồn bã sợ cô gọi, em có thể giúp Tú vượt khó khăn học tập này thế nào?', 'Rủ Tú ngồi đọc ghép đôi 10 phút giờ ra chơi, kiên nhẫn động viên từng câu Tú đọc trôi chảy dần lên', ['Đặt biệt danh trêu giọng đọc của Tú trước lớp', 'Không thèm chung nhóm đọc với Tú', 'Giục cô giáo đừng bao giờ gọi Tú nữa'],
               '"Đôi bạn cùng tiến" là cách sẻ chia tri thức tuyệt vời nhất trong môi trường học đường.', 'Giúp bạn vượt khó học tập'),
            _q(7, 13, 'advanced', 'Khối 2 có 4 lớp, mỗi lớp đóng góp 25 hộp sữa tươi gửi tặng trẻ em vùng khó khăn. Toàn bộ số sữa đó được đóng đều vào các thùng lớn, mỗi thùng xếp đúng 20 hộp. Hỏi có tất cả bao nhiêu thùng sữa yêu thương được chuyển đi?', '5 thùng sữa (100 : 20 = 5)', ['4 thùng sữa', '6 thùng sữa', '10 thùng sữa'],
               'Tổng số sữa = 4 x 25 = 100 hộp; đóng mỗi thùng 20 hộp được 100 : 20 = 5 thùng sữa!', 'Bài toán đóng gói quà tặng'),
            _q(7, 14, 'advanced', 'Vì sao khi tham gia các hoạt động thiện nguyện chia sẻ giúp đỡ cộng đồng từ tiểu học, chính bản thân các em nhỏ cũng nhận lại được món quà vô giá?', 'Vì lòng nhân ái nuôi dưỡng tâm hồn ấm áp hạnh phúc, giúp các em biết trân trọng cuộc sống bình yên hiện tại và biết sống có trách nhiệm với mọi người', ['Vì chắc chắn sẽ được nhận lại tiền gấp đôi', 'Vì làm từ thiện xong không cần phải đi học', 'Không nhận được giá trị tinh thần nào cả'],
               '"Bàn tay tặng hoa hồng luôn phảng phất hương thơm" – cho đi yêu thương chính là nuôi dưỡng hạnh phúc nội tâm!', 'Giá trị nhân văn của sẻ chia'),
            _q(7, 15, 'advanced', 'Bạn Hùng nói: "Nhà tớ bình thường chẳng giàu có dư dả tiền bạc gì thì làm sao giúp được bạn gặp khó khăn?". Em giúp Hùng nhận ra điều gì?', 'Sẻ chia không cần giàu tiền bạc: một lời hỏi thăm, cuốn truyện cũ sạch hay buổi chép bài hộ đều là giúp đỡ vô giá từ trái tim!', ['Đúng rồi, chỉ nhà giàu mới làm việc tốt giúp bạn được', 'Đợi lớn lên kiếm thật nhiều tiền rồi mới cần quan tâm bạn', 'Bảo Hùng đi vay tiền bạn khác để giúp'],
               'Trái tim giàu lòng yêu thương luôn tìm được ngàn cách giúp ích không phụ thuộc vào tiền bạc!', 'Giúp đỡ từ trái tim'),
        ]
    ))

    # BÀI 8: Tôn trọng sự khác biệt của bạn bè
    lessons.append(make_lesson(
        'daoduc2-c2', 'daoduc2-b08', 'Bài 8. Tôn trọng Sự khác biệt của Bạn bè', 8,
        'Nhận ra mỗi người bạn đều có nét riêng về ngoại hình, tính cách, sở thích, hoàn cảnh; biết tôn trọng, không phân biệt đối xử hay chế giễu',
        ['Tôn trọng sự khác biệt', 'Không chế giễu ngoại hình', 'Hòa nhập đa dạng'],
        [
            _q(8, 1, 'basic', 'Vì sao trong một lớp học 35 bạn lại có bạn thích vẽ, bạn mê đá bóng, bạn nói giọng miền Bắc, bạn nói giọng miền Nam hay có bạn tóc xoăn, bạn tóc thẳng?', 'Vì mỗi con người là một cá thể độc đáo mang những nét riêng tự nhiên về ngoại hình, năng khiếu, văn hóa vùng miền và sở thích', ['Vì có một số bạn làm sai quy định đồng phục', 'Vì mọi người cần phải giống hệt nhau như rô-bốt', 'Vì các bạn cố tình làm khác đi để trêu cô giáo'],
               'Sự đa dạng làm lớp học và thế giới xung quanh trở nên phong phú, nhiều màu sắc tươi đẹp.', 'Hiểu về sự khác biệt',
               fig=table_fig('Tôn trọng Sự khác biệt', ['Khía cạnh', 'Cách ứng xử văn minh'], [['Ngoại hình', 'Không đặt tên xấu'], ['Giọng nói vùng', 'Lắng nghe, tôn trọng'], ['Sở thích riêng', 'Tôn trọng, không ép'], ['Khuyết tật', 'Hỗ trợ tế nhị, gần']])),
            _q(8, 2, 'basic', 'Hành vi nào sau đây là THIẾU TÔN TRỌNG sự khác biệt của bạn bè và gây tổn thương tâm lí sâu sắc cho bạn?', 'Đặt biệt danh xấu xí trêu chọc vóc dáng (béo, gầy, thấp, đeo kính) hoặc nhại giọng nói quê hương của bạn để cười cợt', ['Tôn trọng sở thích đọc sách khác với sở thích chơi cờ của bạn', 'Lắng nghe bạn kể chuyện phong tục Tết quê bạn ấy', 'Cổ vũ năng khiếu hát hay của bạn'],
               'Nói không với trêu chọc ngoại hình (body shaming) và kì thị vùng miền ngay từ tuổi tiểu học!', 'Phòng chống chế giễu bạn'),
            _q(8, 3, 'basic', 'Khi thấy một bạn nam thích môn Gấp giấy Origami hoặc nấu ăn, hay một bạn nữ thích chơi cờ vua và đá cầu, chúng ta nên có thái độ thế nào?', 'Tôn trọng, khích lệ và chơi hòa đồng vui vẻ vì năng khiếu và sở thích lành mạnh không phân biệt bạn nam hay bạn nữ', ['Cười chê bạn nam sao chơi trò con gái yếu ớt', 'Cấm bạn nữ tham gia giải cờ vua của lớp', 'Ép buộc bạn chỉ được chơi đúng một môn'],
               'Mỗi bạn có quyền phát triển tài năng và sở thích tích cực riêng mà không bị rập khuôn giới tính.', 'Tôn trọng sở thích cá nhân'),
            _q(8, 4, 'basic', 'Nếu trong lớp có một bạn đeo máy trợ thính hoặc phải ngồi xe lăn di chuyển, cách kết bạn tốt nhất của tập thể lớp là gì?', 'Cư xử bình đẳng thân thiện, chủ động đẩy nhẹ xe giúp khi đi qua dốc nếu bạn đồng ý và rủ bạn tham gia các trò chơi phù hợp để bạn không cô đơn', ['Nhìn chằm chằm tò mò bàn tán xì xào sau lưng bạn', 'Gạt bạn ra khỏi mọi hoạt động chung của lớp', 'Chạy lại tháo thử thiết bị trợ thính của bạn'],
               'Hòa nhập, tôn trọng và hỗ trợ đúng lúc giúp mọi bạn nhỏ đều được hưởng trọn niềm vui học đường.', 'Hòa nhập với bạn khuyết tật'),
            _q(8, 5, 'basic', 'Bạn Minh là người dân tộc Tày mới chuyển về học chung lớp em ở thành phố, đôi lúc phát âm tiếng Kinh còn hơi ngọng và mặc trang phục truyền thống ngày hội rất đẹp. Cả lớp nên làm gì?', 'Chào đón thân thiện, khen ngợi nét đẹp văn hóa dân tộc của Minh và nhẹ nhàng giúp Minh luyện đọc phát âm tự nhiên hơn', ['Nhại giọng của Minh để cả bàn cười ồ lên', 'Bắt Minh phải giấu không được kể về dân tộc mình', 'Không cho Minh ngồi chung bàn'],
               '54 dân tộc anh em Việt Nam cùng gắn bó yêu thương tạo nên vườn hoa văn hóa rực rỡ thống nhất.', 'Đoàn kết các dân tộc'),
            _q(8, 6, 'basic', 'Trong buổi thảo luận nhóm, ý tưởng vẽ báo tường của bạn Hà hơi khác với số đông nhưng rất độc đáo sáng tạo. Cả nhóm nên lắng nghe thế nào?', 'Lắng nghe hết trình bày của Hà, khen ngợi điểm sáng tạo và cùng bàn bạc kết hợp hài hòa ý tưởng tốt nhất cho cả nhóm', ['Gạt phăng ngay lập tức bảo ý kiến lạ đời là ngốc nghếch', 'Cười phá lên không cho Hà nói hết câu', 'Bắt Hà ngồi im không được nêu ý kiến nữa'],
               'Tôn trọng quan điểm khác biệt trong làm việc nhóm khơi nguồn cho nhiều sáng kiến đột phá!', 'Tôn trọng ý kiến khác biệt'),
            _q(8, 7, 'application', 'Bạn Tí hay bị các bạn bàn trên gọi trêu là "Tí Còi" vì bạn thấp bé nhất lớp khiến Tí rất buồn tủi không muốn đi học. Là lớp phó học tập hoặc bạn thân của Tí, em giải quyết thế nào?', 'Nhắc các bạn gọi đúng tên đẹp của Tí, phân tích trêu ngoại hình là xấu tính và động viên Tí tự tin vì bạn chạy nhanh và vẽ rất giỏi', ['Cười theo đặt thêm biệt danh mới dài hơn cho vui', 'Bảo Tí tự nghỉ học chuyển lớp khác đi', 'Đánh các bạn bàn trên để trả thù'],
               'Gọi đúng tên thật đầy tôn trọng và ghi nhận điểm mạnh của bạn giúp bạn lấy lại sự tự tin.', 'Ngăn chặn đặt biệt danh xấu'),
            _q(8, 8, 'application', 'Khảo sát sở thích môn năng khiếu cuối tuần của 36 bạn lớp 2A thu được số liệu ở biểu đồ dưới đây (12 bạn thích Vẽ, 10 bạn thích Bóng đá, 8 bạn thích Âm nhạc, 6 bạn thích Cờ vua). Số liệu này chứng minh điều gì?', 'Các bạn có sở thích đa dạng khác nhau ở nhiều môn lành mạnh khác nhau (tổng 12 + 10 + 8 + 6 = 36 bạn) và môn nào cũng thú vị đáng quý', ['Tất cả mọi người đều phải thích mỗi bóng đá', 'Các bạn thích cờ vua là sai vì ít người chọn nhất', 'Cả lớp đều giống hệt nhau'],
               'Sự đa dạng sở thích làm lớp học có đủ họa sĩ, cầu thủ, ca sĩ và kì thủ bổ sung cho nhau!', 'Đọc biểu đồ đa dạng sở thích',
               fig=bars_fig('Sở thích năng khiếu lớp 2A', ['Mĩ thuật', 'Bóng đá', 'Âm nhạc', 'Cờ vua'], [12, 10, 8, 6], 'bạn')),
            _q(8, 9, 'application', 'Hôm liên hoan lớp, một bạn có cơ địa dị ứng đậu phộng nên không ăn được món bánh có hạt đậu phộng, chỉ ăn hoa quả. Một bạn khác trêu "kén ăn làm điệu". Em giải thích giúp bạn thế nào?', 'Giải thích nhẹ rằng sức khỏe cơ địa mỗi người khác nhau, dị ứng thức ăn có thể gây nguy hiểm nổi mẩn khó thở chứ không phải bạn kén chọn làm điệu', ['Ép bạn dị ứng phải ăn thử một miếng cho quen', 'Cười theo lời trêu kén ăn', 'Bỏ thêm đậu phộng vào đĩa hoa quả của bạn'],
               'Hiểu biết về sự khác biệt sức khỏe giúp ta không vô tình gây nguy hiểm hay tổn thương cho bạn!', 'Tôn trọng khác biệt sức khỏe'),
            _q(8, 10, 'application', 'Bạn An viết chữ bằng tay trái rất đẹp và sạch sẽ. Một bạn ngồi bên bảo: "Sao cậu viết tay trái kì cục vậy, phải ép chuyển sang tay phải mới bình thường chứ!". Nhận xét của bạn ngồi bên đúng hay sai?', 'Sai! Thuận tay trái là đặc điểm sinh học tự nhiên bình thường của khoảng một phần mười dân số thế giới, hoàn toàn đáng tôn trọng như thuận tay phải', ['Đúng, tất cả mọi người bắt buộc phải viết tay phải', 'Sai, viết tay trái là siêu nhân hơn hẳn tay phải', 'Nên giấu bút của bạn đi'],
               'Tôn trọng người thuận tay trái thể hiện sự hiểu biết khoa học và văn minh hiện đại.', 'Tôn trọng bạn thuận tay trái'),
            _q(8, 11, 'application', 'Nếu một bạn mới chuyển từ vùng quê miền núi xuống thành phố học chưa quen cách dùng thiết bị hiện đại ở lớp như bảng tương tác, em nên làm gì?', 'Nhiệt tình hướng dẫn từng bước nhẹ nhàng cho bạn làm quen, đồng thời thích thú lắng nghe bạn kể về thiên nhiên rừng núi quê bạn', ['Chế giễu bạn là người lạc hậu không biết gì', 'Không cho bạn chạm vào đồ dùng lớp học', 'Cười khúc khích mỗi khi bạn hỏi'],
               'Giao lưu học hỏi hai chiều giúp cả hai bạn đều mở mang hiểu biết và gắn kết thân tình.', 'Hòa nhập bạn mới vùng miền'),
            _q(8, 12, 'application', 'Trong một bức tranh tập thể, một bạn tô màu chiếc lá cây màu tím mộng mơ thay vì màu xanh lá truyền thống và giải thích đây là "khu vườn cổ tích mùa thu". Em đánh giá thế nào?', 'Tôn trọng và khen ngợi trí tưởng tượng nghệ thuật phong phú độc đáo của bạn vì hội họa khuyến khích sự sáng tạo tự do không gò bó', ['Xé tranh của bạn bảo sai kiến thức tự nhiên rồi', 'Cầm bút xanh tô đè nát lên bức tranh bạn', 'Chê bạn bị mù màu'],
               'Không gian sáng tạo tôn trọng góc nhìn nghệ thuật riêng biệt nuôi dưỡng những tâm hồn nghệ sĩ.', 'Tôn trọng góc nhìn sáng tạo'),
            _q(8, 13, 'advanced', 'Một vườn hoa có 4 khóm hoa khác màu nở rộ cùng lúc: 12 bông cúc vàng, 10 bông hồng đỏ, 8 bông đồng tiền cam và 6 bông cẩm tú cầu tím. Hỏi vườn hoa rực rỡ sắc màu ấy có tất cả bao nhiêu bông hoa khoe sắc?', '36 bông hoa rực rỡ đa sắc màu', ['30 bông hoa', '32 bông hoa', '40 bông hoa'],
               '12 + 10 + 8 + 6 = 36 bông hoa – chính sự đa dạng sắc màu làm khu vườn đẹp hơn hẳn một màu đơn điệu!', 'Ẩn dụ Vườn hoa đa sắc'),
            _q(8, 14, 'advanced', 'Vì sao người ta nói: "Tôn trọng sự khác biệt không có nghĩa là chấp nhận những hành vi xấu hay vi phạm nội quy"?', 'Vì khác biệt đáng tôn trọng là nét riêng tự nhiên, sở thích lành mạnh; còn hành vi xấu như bắt nạt, xả rác hay nói dối cần góp ý sửa ngay', ['Vì bất kì hành vi nào kể cả đánh bạn cũng gọi là sở thích riêng', 'Vì mọi người đều phải làm việc xấu giống nhau', 'Không thể phân biệt được hai điều đó'],
               'Phân biệt rạch ròi giữa "đa dạng bản sắc tích cực" và "vi phạm chuẩn mực đạo đức" giúp tư duy phản biện cực sáng suốt!', 'Giới hạn của sự khác biệt'),
            _q(8, 15, 'advanced', 'Lớp học hạnh phúc là lớp học như thế nào đối với tất cả mọi thành viên mang những nét riêng khác nhau?', 'Là nơi mọi bạn nhỏ đều được an toàn, được lắng nghe, không bị chế giễu phân biệt và tự tin phát huy điểm mạnh riêng của chính mình', ['Là nơi mọi học sinh đều phải cắt tóc và thích một món giống hệt nhau', 'Là nơi chỉ bạn học giỏi nhất mới được nói chuyện', 'Là nơi ai thấp bé hay khác lạ đều bị trêu'],
               'Tôn trọng sự khác biệt là nền móng kiến tạo "Trường học Hạnh phúc" đích thực!', 'Kiến tạo lớp học hạnh phúc'),
        ]
    ))

    return lessons
